  function canBC(){ if(st.bc || !quyen().bc) return; if(!coMayChu()) { st.bc = dungMau().bc; return; } tai('bc', 'baoCaoThangHe', { thang:st.thang }, function(r){ st.bc = r || { ok:false, loi:1 }; }); }
