      var m = { ten:g('v20-mt-ten'), chiSo:g('v20-mt-cs'), giaTriDau:Number(g('v20-mt-dau')), mucTieu:Number(g('v20-mt-muc')), hanLuc:g('v20-mt-han'), chuSo:g('v20-mt-chu') };
