(function(){
/* ═══════════════════════════════════════════════════════════════
   GITA 365 — MÀN BỘ NÃO VẬN HÀNH V50 (R01–R03)
   Đọc thẳng máy chủ (may-chu/bo-nao-van-hanh.js): phân hệ nào đang chạy,
   chạy theo chế độ nào, nhịp gần nhất làm được gì. Super Admin có hai nút:
   "Chạy thử" (đi đủ bước, chỉ đọc) và "Chạy thật một lượt".
   Không có máy chủ thì nói thẳng — không vẽ số giả cho một bảng giám sát.
   ═══════════════════════════════════════════════════════════════ */
'use strict';
var G = window.G || {}; window.G = G; G.VIEWS = G.VIEWS || {};
(function(){
  var U = G.U, h = U.h, ic = U.ic;
  var st = { ai:'', d:null, dang:false, loi:'', chay:null, dangChay:false };
  function coMayChu(){ return !!(G.API_CAP_PHEP && G.PHIEN_TOKEN); }
  function laR01(){ return !!(G.S && G.S.role === 'R01'); }
  function veLai(){ if(G.S && G.S.view === 'bo-nao-van-hanh' && G.render) G.render(); }
  function gio(s){ try { var d = new Date(s); return ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2) + ' · ' + d.getDate() + '/' + (d.getMonth() + 1); } catch(e){ return s; } }
  var TT = { ok:['ổn','var(--ok)'], canhBao:['cảnh báo','var(--warn)'], loi:['lỗi','var(--gita-do)'] };
  var KIEU = { nhip:'Nhịp mỗi giờ', khachMoi:'Khách mới', tay:'Chạy tay', thu:'Chạy thử' };

  function nap(){
    var ai = String((G.S && G.S.acc && G.S.acc.u) || '');
    if(st.ai !== ai) st = { ai:ai, d:null, dang:false, loi:'', chay:null, dangChay:false };
    if(!coMayChu() || st.d || st.dang) return;
    st.dang = true;
    G.goiMayChu('docBoNao', {}).then(function(r){
      st.dang = false;
      if(r && r.ok) st.d = r; else st.loi = (r && r.error) || 'Chưa đọc được bộ não.';
      veLai();
    });
  }
  G.boNaoChay = function(that){
    if(st.dangChay) return;
    st.dangChay = true; veLai();
    G.goiMayChu('chayThuBoNao', { that: !!that }).then(function(r){
      st.dangChay = false; st.chay = r; st.d = null;   /* đọc lại lịch sử */
      if(!(r && r.ok)) U.toast((r && r.error) || 'Chưa chạy được.', 'err');
      else U.toast(that ? 'Đã chạy một lượt thật.' : 'Đã chạy thử — không ghi gì.', 'ok');
      veLai();
    });
  };

  function phanHe(ds){
    return '<div class="bn-phanhe">' + ds.map(function(p){
      return '<div class="card bn-ph' + (p.bat ? '' : ' bn-tat') + '"><div class="bn-ph-dau"><b>' + h(p.ten) + '</b>' +
        '<span class="bn-pill" style="--bp:' + (p.bat ? 'var(--ok)' : 'var(--ink-4)') + '">' + (p.bat ? 'đang chạy' : 'tắt') + '</span></div>' +
        '<p class="tiny" style="margin:4px 0 0">' + h(p.cheDo) + '</p>' + (p.moTa ? '<p class="tiny muted" style="margin:4px 0 0">' + h(p.moTa) + '</p>' : '') + '</div>';
    }).join('') + '</div>';
  }
  function buoc(kq){
    return '<div class="bn-buoc">' + (kq.buoc || []).map(function(b){
      var t = TT[b.tt] || TT.ok, so = [];
      if(b.ma === 'PHAN_CONG') so.push(b.so + ' nhà chưa có Tư vấn' + (kq.that ? ' · đã giao ' + (b.daGan || 0) : ' · sẽ giao ' + (b.seGan || 0)) + (b.thieu ? ' · thiếu Tư vấn ' + b.thieu : ''));
      if(b.ma === 'DEN_CHAM') so.push('xanh ' + b.xanh + ' · vàng ' + b.vang + ' · đỏ ' + b.do + (kq.that ? ' · đưa lên đầu ' + (b.duaLen || 0) : ''));
      if(b.ma === 'HEN_CRM') so.push(b.tong + ' hẹn quá hạn' + (b.theoNguoi && b.theoNguoi.length ? ' · ' + b.theoNguoi.slice(0, 4).map(function(x){ return x.ai + ' ' + x.n; }).join(', ') : ''));
      if(b.ma === 'CONG_NO') so.push((b.so || 0) + ' kỳ quá hạn · ' + U.bdGon(b.tongConNo || 0) + ' đ · chưa ai nhắc ' + (b.chuaAiNhac || 0));
      if(b.ma === 'KHO_CHO_DUYET') so.push((b.so || 0) + ' bản nháp chờ ba chữ ký');
      if(b.ma === 'BAO_DONG') so.push(b.soNgo ? b.soNgo + ' tài khoản đáng ngờ' : 'không có dấu hiệu' + (b.mailCuu ? '' : ' · chưa nạp email cứu hệ'));
      if(b.ma === 'AGENT') so.push(!b.so ? 'không có tuyến tự chạy nào đang dở' : kq.that ? (b.daChay || 0) + '/' + b.so + ' tuyến chạy tiếp một chặng' : b.so + ' tuyến sẽ chạy tiếp' );
      if(b.ma === 'CHUP_DO') so.push(b.daChup ? 'đã chụp' : b.seChup ? 'sẽ chụp' : 'hôm nay đã có');
      return '<div class="bn-b" style="--bt:' + t[1] + '"><span class="bn-pill" style="--bp:' + t[1] + '">' + t[0] + '</span><div><b>' + h(b.ten) + '</b>' +
        '<p class="tiny muted" style="margin:2px 0 0">' + h(so.join(' ') || '') + (b.ghiChu ? ' — ' + h(b.ghiChu) : '') + (b.loi ? ' — ' + h(b.loi) : '') + '</p></div></div>';
    }).join('') + '</div>';
  }
  function lichSu(ds){
    if(!ds.length) return '<p class="tiny muted">Chưa có nhịp nào được ghi. Ca làm việc đầu tiên bắt đầu ở phút 0 của giờ kế tiếp sau khi triển khai.</p>';
    return '<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Lúc</th><th>Loại</th><th>Kết quả</th></tr></thead><tbody>' + ds.slice(0, 24).map(function(x){
      var kq0 = x.kieu === 'nhip' && x.lan != null ? 'lượt ' + (x.lan + 1) + '/6 · ' : '';
      var kq = x.kieu === 'khachMoi' ? (x.maKH + ' → ' + ((x.phanCong && x.phanCong.tuVan) || (x.phanCong && x.phanCong.ket) || '')) :
        x.tom ? (kq0 + x.tom.canhBao + ' cảnh báo · ' + x.tom.loi + ' lỗi · ' + (x.ms || 0) + ' ms') : '';
      return '<tr><td class="mono tiny">' + h(gio(x.luc)) + '</td><td>' + h(KIEU[x.kieu] || x.kieu) + (x.that ? '' : ' <span class="tiny muted">(không ghi)</span>') + '</td><td class="tiny">' + h(kq) + '</td></tr>';
    }).join('') + '</tbody></table></div>';
  }

  document.addEventListener('click', function(e){
    var b = e.target.closest && e.target.closest('[data-bn]'); if(!b || b.disabled) return;
    G.boNaoChay(b.getAttribute('data-bn') === 'that');
  });

  G.VIEWS['bo-nao-van-hanh'] = function(){
    nap();
    var o = '<header class="ph"><div class="eyebrow">V50 · vận hành 24/7</div><h1>Bộ não vận hành</h1>' +
      '<p class="lead">Làm 30 phút · nghỉ 30 phút, lặp liên tục 24/7 (sáu lượt ở phút 0–25 mỗi giờ). Mỗi lượt bộ não tự giao Tư vấn cho nhà mới, đưa nhà lâu không ai chạm lên đầu danh sách gọi, đếm hẹn và công nợ quá hạn, soát báo động, chạy tiếp đội Agent, chụp số đo. Có khách kích hoạt tài khoản là chạy ngay. Nội dung cho khách và mã nguồn vẫn đi qua chữ ký của người.</p></header>';
    if(!coMayChu())
      return o + '<div class="card pad"><b>Bảng này đọc thẳng máy chủ.</b><p class="tiny muted" style="margin:6px 0 0">Đăng nhập bản có máy chủ (gita365.pages.dev) để thấy phân hệ đang chạy và nhịp gần nhất. Bản thử không có số để hiện — bảng giám sát không vẽ số giả.</p></div>';
    if(laR01())
      o += '<div class="card pad mb bn-nut"><div><b>Chạy bộ não bằng tay</b><p class="tiny muted" style="margin:2px 0 0">Chạy thử đi đủ các bước và chỉ đọc; chạy thật làm đúng việc của một nhịp.</p></div>' +
        '<div class="row" style="gap:8px;flex-wrap:wrap"><button class="btn" data-bn="thu"' + (st.dangChay ? ' disabled' : '') + '>' + ic('pulse', 'w-4 h-4') + 'Chạy thử (không ghi)</button>' +
        '<button class="btn pri" data-bn="that"' + (st.dangChay ? ' disabled' : '') + '>' + ic('arrow', 'w-4 h-4') + 'Chạy thật một lượt</button></div></div>';
    if(st.dangChay) o += '<div class="card pad mb"><p class="tiny">Bộ não đang chạy…</p></div>';
    if(st.chay && st.chay.ok)
      o += '<section class="card pad mb"><div class="tc-khoi-dau"><b>' + (st.chay.that ? 'Lượt vừa chạy thật' : 'Lượt vừa chạy thử — chưa ghi gì') + '</b><span class="tiny muted">' + h(gio(st.chay.luc)) + ' · ' + (st.chay.ms || 0) + ' ms</span></div>' + buoc(st.chay) + '</section>';
    if(st.loi) return o + '<div class="card pad"><p class="tiny" style="color:var(--gita-do)">' + h(st.loi) + '</p></div>';
    if(!st.d) return o + '<div class="card pad"><p class="tiny muted">Đang đọc bộ não…</p></div>';
    o += '<section class="mb"><h2 class="h2">Phân hệ</h2>' + phanHe(st.d.phanHe || []) + '</section>';
    o += '<section class="card pad mb"><div class="tc-khoi-dau"><b>Nhịp gần đây</b><span class="tiny muted">' + (st.d.nhipCuoi ? 'nhịp mỗi giờ gần nhất: ' + h(gio(st.d.nhipCuoi)) : 'chưa có nhịp mỗi giờ') + '</span></div>' + lichSu(st.d.lanChay || []) + '</section>';
    return o;
  };
})();

})();

/* ═════════ src/studio-he.js ═════════ */
(function(){
/* ═══════════════════════════════════════════════════════════════
   GITA 365 — HỆ ĐIỀU HÀNH XƯỞNG PHIM / STUDIO (chuyên sâu theo nghề)

   Lớp ĐIỀU HÀNH xưởng (quy trình · vai trò · chuẩn · kho · công suất ·
   đo lường) — tách hẳn khỏi xưởng DỰNG VIDEO (G.VIEWS['studio'] trong
   studio.js, có gói nghề + máy chủ). Màn này KHÔNG đụng studio.js, không
   gọi máy chủ, không gói nghề: chỉ là bàn điều hành bằng khung chuẩn thật
   của nghề làm phim 9:16; con số vận hành để mẫu (ghi rõ nhãn).

   View key: studio-he. Mở cho qt_trang (Super Admin / Admin). Dùng chung
   ô trạng thái gdNV + G.gdTick (khoá riêng sx-*). 6 module qua tab CSS.
   ═══════════════════════════════════════════════════════════════ */
'use strict';
var G = window.G || {}; window.G = G; G.VIEWS = G.VIEWS || {};
(function(){
  var U = G.U, h = U.h, ic = U.ic;
  var BANDC = { DO:'#BE0E16', VANG:'#B4720F', XANH:'#0B7350' };
  var TT = { '':{t:'Chưa',c:'--ink-4'}, dang:{t:'Đang làm',c:'--warn'}, xong:{t:'Đã xong',c:'--ok'} };

  /* ── BẢNG (tái dùng khung .gd-tb, cột đèn tuỳ chọn) ── */
  function veBang(b){
    var den = (b.den==null)?-1:b.den;
    var head = '<tr>'+ b.cols.map(function(c){ return '<th>'+h(c)+'</th>'; }).join('') +'</tr>';
    var body = b.rows.map(function(r){
      return '<tr>'+ r.map(function(cell,ci){
        if(ci===den){ var m=BANDC[cell]||'#73849F'; return '<td class="ta-c"><span class="gd-den" style="--m:'+m+'" title="'+h(cell)+'"></span></td>'; }
        return '<td>'+h(String(cell))+'</td>';
      }).join('') +'</tr>';
    }).join('');
    return '<div class="gd-wrap"><table class="gd-tb"><thead>'+head+'</thead><tbody>'+body+'</tbody></table></div>';
  }

  /* ══ MODULE A · QUY TRÌNH SẢN XUẤT (10 khâu) ══ */
  var QUYTRINH = [
    ['Ý tưởng & Brief','Chốt mục tiêu, thông điệp chính, đối tượng xem và lời kêu gọi (CTA) trước khi viết.',
      ['Đầu ra: Brief 1 trang','Phụ trách: Sáng tạo','Công cụ: mẫu brief','~0,5 ngày (mẫu)']],
    ['Kịch bản','Viết lời theo cấu trúc 8 phần, bắt đầu bằng hook 3 giây. Lời đọc tự nhiên, đúng giọng GITA.',
      ['Đầu ra: Kịch bản + lời đọc','Phụ trách: Biên kịch','Công cụ: Ngân khố câu','~0,5 ngày (mẫu)']],
    ['Storyboard / Shot list','Phân cảnh, phác khung hình dọc 9:16, liệt kê từng cảnh cần quay/dựng.',
      ['Đầu ra: Storyboard + shot list','Phụ trách: Đạo diễn','Công cụ: khung 9:16','~0,5 ngày (mẫu)']],
    ['Chuẩn bị sản xuất','Chọn MC/nhân vật, đạo cụ, bối cảnh; lên lịch quay và checklist thiết bị.',
      ['Đầu ra: Lịch quay + checklist','Phụ trách: Quản lý SX','Công cụ: lịch · checklist','~1 ngày (mẫu)']],
    ['Quay / Thu','Quay theo shot list, thu tiếng/giọng. Giữ bố cục dọc, đủ ánh sáng, đủ b-roll dự phòng.',
      ['Đầu ra: Footage thô','Phụ trách: Quay phim','Công cụ: máy quay / điện thoại','~1 ngày (mẫu)']],
    ['Dựng thô (rough cut)','Ghép cảnh theo kịch bản, canh nhịp và thời lượng, chốt mạch kể trước khi tinh chỉnh.',
      ['Đầu ra: Bản dựng thô','Phụ trách: Dựng phim','Công cụ: phần mềm dựng','~0,5 ngày (mẫu)']],
    ['Dựng tinh','Chỉnh màu phim, xử lý âm thanh, phối nhạc nền bản quyền, gắn phụ đề và motion/đồ hoạ.',
      ['Đầu ra: Bản hoàn chỉnh','Phụ trách: Dựng + Âm thanh + Motion','Công cụ: kho nhạc · template','~1 ngày (mẫu)']],
    ['Duyệt','Soát nội dung, chuẩn thương hiệu, pháp lý & bản quyền, ẩn danh dữ liệu khách trước khi ra.',
      ['Đầu ra: Bản đã duyệt','Phụ trách: Giám đốc / Quản trị','Công cụ: checklist chuẩn','~0,3 ngày (mẫu)']],
    ['Xuất bản & phân phối','Xuất đúng định dạng 9:16, đặt lịch, đăng lên kênh và gắn liên kết đo lường.',
      ['Đầu ra: Video phát hành','Phụ trách: Marketing','Công cụ: lịch đăng','~0,2 ngày (mẫu)']],
    ['Đo lường & học','Theo dõi lượt xem, giữ chân, chia sẻ, chuyển đổi; rút bài cho video kế tiếp.',
      ['Đầu ra: Thẻ kết quả','Phụ trách: Phân tích','Công cụ: bảng đo','liên tục']]
  ];
  function veQuyTrinh(){
    return '<div>'+ QUYTRINH.map(function(s,i){
      return '<div class="sx-step"><span class="sx-num">'+(i+1)+'</span><div>'+
        '<div class="sx-st-b">'+h(s[0])+'</div><div class="sx-st-d">'+h(s[1])+'</div>'+
        '<div class="sx-meta">'+ s[2].map(function(c){ return '<span class="sx-chip">'+h(c)+'</span>'; }).join('') +'</div>'+
      '</div></div>';
    }).join('') +'</div>';
  }

  /* ══ MODULE B · VAI TRÒ & ĐỘI NGŨ XƯỞNG ══ */
  function veVaiTro(){ return veBang({ cols:['Vai trong xưởng','Nhiệm vụ chính','Kỹ năng lõi','Đầu ra','KPI (mẫu)'], den:-1, rows:[
    ['Biên kịch','Viết kịch bản & lời đọc theo cấu trúc chuẩn','Kể chuyện · hook · ngôn ngữ GITA','Kịch bản đạt duyệt','% kịch bản duyệt lần 1'],
    ['Đạo diễn sáng tạo','Chốt ý tưởng, storyboard, mạch cảm xúc','Tư duy hình ảnh · nhịp','Storyboard · hướng hình','Điểm cảm xúc video'],
    ['Quay phim','Quay đúng shot list, đủ sáng, bố cục dọc','Máy quay · ánh sáng · bố cục','Footage đạt chuẩn','% cảnh dùng được'],
    ['Dựng phim','Dựng thô & tinh, canh nhịp, chỉnh màu','Phần mềm dựng · màu','Bản dựng hoàn chỉnh','Thời gian dựng / video'],
    ['Motion / Đồ hoạ','Chữ động, hiệu ứng, nhận diện thương hiệu','After Effects · thiết kế','Gói motion','Chuẩn thương hiệu đạt'],
    ['Âm thanh','Xử lý tiếng, chuẩn âm lượng, phối nhạc','Mix · nhạc bản quyền','Âm thanh sạch','Âm lượng đạt chuẩn'],
    ['Phụ đề / Biên tập','Gắn phụ đề, soát chính tả, cỡ chữ','Ngôn ngữ · timing','Phụ đề chuẩn','% video có phụ đề'],
    ['Quản lý sản xuất','Giữ lịch, điều phối đội, chốt hạn','Điều phối · kế hoạch','Pipeline đúng hạn','% dự án đúng hạn'],
    ['Phát hành','Xuất bản, đặt lịch, phối marketing','Nền tảng · lịch đăng','Video lên kênh','Số video phát hành']
  ]}); }

  /* ══ MODULE C · CHUẨN CHẤT LƯỢNG 9:16 ══ */
  function veChuan(){ return veBang({ cols:['Nhóm chuẩn','Tiêu chí','Ngưỡng','Vì sao'], den:-1, rows:[
    ['Kỹ thuật','Tỷ lệ khung hình','9:16 dọc (1080×1920)','Đúng nền tảng video dọc'],
    ['Kỹ thuật','Âm lượng','≈ −14 LUFS (mẫu)','Nghe đều, không vỡ tiếng'],
    ['Kỹ thuật','Độ phân giải / nét','≥ 1080p','Hình sắc trên điện thoại'],
    ['Nội dung','Hook mở đầu','≤ 3 giây','Giữ người xem khỏi lướt'],
    ['Nội dung','Độ dài','30–210 giây','Đủ ý, không lê thê'],
    ['Nội dung','Thông điệp','1 ý chính','Rõ ràng, dễ nhớ'],
    ['Thương hiệu','Logo & màu','Logo góc + màu GITA','Nhận diện nhất quán'],
    ['Thương hiệu','Nhạc nền','Có bản quyền','Tránh bị gỡ / phạt'],
    ['Khả dụng','Phụ đề','Luôn bật','Xem được khi tắt tiếng'],
    ['Khả dụng','Cỡ chữ & vùng an toàn','Chữ to, trong khung an toàn','Đọc được, không bị cắt'],
    ['Pháp lý','Dữ liệu khách','Ẩn danh theo hiến pháp','Bảo mật khách hàng'],
    ['Kêu gọi','CTA','Rõ 1 hành động','Dẫn tới bước tiếp theo']
  ]}); }

  /* ══ MODULE D · KHO SẢN XUẤT ══ */
  function veKho(){ return veBang({ cols:['Loại kho','Nội dung','Số mục (mẫu)','Đèn','Ghi chú'], den:3, rows:[
    ['Template 9:16','Khung mở đầu · thân · CTA','24','XANH','Chuẩn thương hiệu'],
    ['Nhạc nền bản quyền','Theo cảm xúc · nhịp độ','60','XANH','Đã có giấy phép'],
    ['Tư liệu / footage','Cảnh nền · b-roll','180','VANG','Bổ sung dần'],
    ['Brand kit','Logo · màu · font','1 bộ','XANH','Khoá chuẩn, không đổi tuỳ tiện'],
    ['Hiệu ứng / chuyển cảnh','Motion · transition','36','XANH','—'],
    ['Giọng đọc tham chiếu','Mẫu giọng xử lý tại máy','8','XANH','Không rời thiết bị']
  ]}); }

  /* ══ MODULE E · CÔNG SUẤT & LỊCH ══ */
  function veCongSuat(){
    var loai = veBang({ cols:['Loại nội dung','Mục tiêu','Độ dài','Nhịp/tháng (mẫu)'], den:-1, rows:[
      ['Phim cầu nối','Nối cảm xúc giữa các tầng','3–4 phút','6'],
      ['Nội dung WOW','Tạo điểm chạm bất ngờ','30–60 giây','12'],
      ['Testimonial khách','Bằng chứng chuyển hoá','1–2 phút','4'],
      ['Video hướng dẫn','Dạy một kỹ năng cụ thể','2–5 phút','8'],
      ['Quảng cáo','Kéo khách mới','15–45 giây','10']
    ]});
    var board = veBang({ cols:['Dự án','Loại','Khâu hiện tại','Phụ trách','Hạn','Đèn'], den:5, rows:[
      ['Phim cầu nối T3','Cầu nối','Dựng tinh','Dựng phim','T5','VANG'],
      ['WOW "3 giây vàng"','WOW','Quay','Quay phim','T4','VANG'],
      ['Testimonial nhà Minh An','Testimonial','Duyệt','Giám đốc','T3','XANH'],
      ['Hướng dẫn "Bảng số gia đình"','Hướng dẫn','Kịch bản','Biên kịch','T6','XANH'],
      ['Quảng cáo tuyển sinh','Quảng cáo','Phát hành','Marketing','T3','XANH']
    ]});
    return U.sec('Loại nội dung GITA','5 dòng sản phẩm của xưởng — mỗi loại một chuẩn & nhịp riêng')+loai+
      U.sec('Bảng công suất & lịch (mẫu)','Dự án đang chạy xếp theo khâu — nối máy chủ sẽ chạy thật')+board;
  }

  /* ══ MODULE F · ĐO LƯỜNG HIỆU QUẢ ══ */
  function veDoLuong(){ return veBang({ cols:['Chỉ số','Ý nghĩa','Mức tốt (mẫu)','Hiện tại (mẫu)','Đèn'], den:4, rows:[
    ['Lượt xem','Số người tiếp cận','—','42.000','XANH'],
    ['Giữ chân 3 giây','% vượt qua hook','≥ 70%','74%','XANH'],
    ['Xem hết','% xem trọn video','≥ 35%','31%','VANG'],
    ['Chia sẻ','Mức lan truyền','≥ 2%','2,4%','XANH'],
    ['Lưu','Giá trị giữ lại','≥ 1%','1,1%','XANH'],
    ['Chuyển đổi','Xem → đăng ký → chốt','≥ 3%','2,6%','VANG']
  ]}); }

  /* ══ NGHIỆP VỤ ĐIỀU HÀNH XƯỞNG (bấm-thao-tác-được) ══ */
  var NV = [
    ['Duyệt brief & ý tưởng video','noi-dung-tiep-thi'],['Giao kịch bản cho biên kịch','studio'],
    ['Duyệt storyboard / shot list','studio'],['Lên lịch quay & phân công đội','phong-ban'],
    ['Soát chuẩn chất lượng 9:16','studio'],['Duyệt nội dung trước phát hành','studio'],
    ['Quản kho template · nhạc · tư liệu','thu-vien'],['Đo hiệu quả video (view · giữ chân · chốt)','do-luong-kh'],
    ['Duyệt ngân sách sản xuất','chi-phi'],['Báo cáo kết quả xưởng phim','do-luong-kh']
  ];
  function veNV(){
    var xong=0;
    var rows = NV.map(function(it,i){
      var id='sx-nv:'+i; var st=(G.S.gdNV||{})[id]||''; if(st==='xong') xong++;
      var t=TT[st];
      var tgt=(G.manCoThat && G.manCoThat(it[1]))?it[1]:'studio';
      var mo=G.allowed?G.allowed(tgt):true;
      var nut=mo?'<button class="btn ghost sm gd-open" data-v="'+h(tgt)+'">Mở '+ic('arrow','w-3 h-3')+'</button>'
               :'<span class="vh-khoa">'+ic('lock','w-3 h-3')+'khoá</span>';
      return '<div class="gd-nvr'+(st==='xong'?' done':'')+'">'+
        '<button class="gd-tick gd-tick-'+(st||'chua')+'" data-gdtick="'+h(id)+'" style="--m:var('+t.c+')" title="Bấm đổi trạng thái">'+
          (st==='xong'?ic('check','w-3 h-3'):st==='dang'?ic('clock','w-3 h-3'):'')+'</button>'+
        '<span class="gd-nvi">'+(i+1)+'</span><span class="gd-nvt">'+h(it[0])+'</span>'+
        '<span class="gd-nvs" style="--m:var('+t.c+')">'+h(t.t)+'</span>'+nut+'</div>';
    }).join('');
    return {html:'<div class="gd-nvlist">'+rows+'</div>', xong:xong};
  }

  G.VIEWS['studio-he'] = function(){
    if(!(typeof G.can==='function' && G.can('qt_trang')))
      return U.lockCard('Hệ điều hành Xưởng phim mở cho Super Admin / Admin. Đăng nhập đúng vai để xem.');

    var o = U.ph({ eyebrow:'XƯỞNG PHIM · ĐIỀU HÀNH CHUYÊN SÂU', ic:'sparkle', grad:1,
      t:'Hệ điều hành Xưởng phim / Studio',
      lead:'Bàn điều hành chuyên môn của xưởng: quy trình 10 khâu, vai trò & đội ngũ, chuẩn chất lượng 9:16, kho sản xuất, công suất & lịch, đo lường. Khung chuẩn thật của nghề làm phim; con số vận hành để mẫu tới khi nối máy chủ.' });

    o += '<div class="row mb" style="gap:8px;flex-wrap:wrap">'+
      '<button class="btn ghost sm" data-v="van-hanh-10">'+ic('arrow','w-3 h-3')+'Bảng điều khiển vận hành</button>'+
      '<button class="btn sm" data-v="lam-phim-10">'+ic('sparkle','w-3 h-3')+'Chương trình 10 bước làm phim</button>'+
      '<button class="btn sm" data-v="ban-dung">'+ic('tools','w-3 h-3')+'Bàn dựng (biên tập tại máy)</button>'+
      '<button class="btn sm" data-v="san-xuat-ai">'+ic('orbit','w-3 h-3')+'Sản xuất phim AI (bộ điều khiển)</button>'+
      (G.allowed && G.allowed('studio') ? '<button class="btn ghost sm" data-v="studio">'+ic('spark','w-3 h-3')+'Mở xưởng dựng video</button>' : '')+
      '</div>';

    o += '<div class="grid g4 mb">'+
      U.stat({k:'Khâu sản xuất', v:String(QUYTRINH.length), d:'quy trình chuẩn'})+
      U.stat({k:'Vai trong xưởng', v:'9', d:'đội ngũ nghề'})+
      U.stat({k:'Loại nội dung', v:'5', d:'dòng sản phẩm'})+
      U.stat({k:'Dự án đang chạy', v:'12', d:'tháng này (mẫu)', c:'var(--gita)'})+'</div>';

    /* 6 module qua tab CSS (radio) — tất cả bảng biểu bên trong */
    o += '<div class="sx">'+
      '<input type="radio" name="sxTab" id="sx-qt" class="sx-radio" checked>'+
      '<input type="radio" name="sxTab" id="sx-vt" class="sx-radio">'+
      '<input type="radio" name="sxTab" id="sx-cl" class="sx-radio">'+
      '<input type="radio" name="sxTab" id="sx-kh" class="sx-radio">'+
      '<input type="radio" name="sxTab" id="sx-cs" class="sx-radio">'+
      '<input type="radio" name="sxTab" id="sx-dl" class="sx-radio">'+
      '<div class="sx-tabbar">'+
        '<label for="sx-qt">'+ic('orbit','w-3 h-3')+'Quy trình 10 khâu</label>'+
        '<label for="sx-vt">'+ic('users','w-3 h-3')+'Vai trò & đội ngũ</label>'+
        '<label for="sx-cl">'+ic('check','w-3 h-3')+'Chuẩn 9:16</label>'+
        '<label for="sx-kh">'+ic('book','w-3 h-3')+'Kho sản xuất</label>'+
        '<label for="sx-cs">'+ic('grid','w-3 h-3')+'Công suất & lịch</label>'+
        '<label for="sx-dl">'+ic('chart','w-3 h-3')+'Đo lường</label>'+
      '</div>'+
      '<div id="sx-p-qt" class="sx-pan">'+U.sec('Quy trình sản xuất — 10 khâu','Từ ý tưởng tới đo lường · mỗi khâu rõ đầu ra · phụ trách · công cụ')+veQuyTrinh()+'</div>'+
      '<div id="sx-p-vt" class="sx-pan">'+U.sec('Vai trò & đội ngũ xưởng','9 vai nghề · nhiệm vụ · kỹ năng lõi · đầu ra · KPI')+veVaiTro()+'</div>'+
      '<div id="sx-p-cl" class="sx-pan">'+U.sec('Chuẩn chất lượng 9:16','Kỹ thuật · nội dung · thương hiệu · khả dụng · pháp lý · CTA')+veChuan()+'</div>'+
      '<div id="sx-p-kh" class="sx-pan">'+U.sec('Kho sản xuất','Template · nhạc bản quyền · tư liệu · brand kit · hiệu ứng · giọng')+veKho()+'</div>'+
      '<div id="sx-p-cs" class="sx-pan">'+veCongSuat()+'</div>'+
      '<div id="sx-p-dl" class="sx-pan">'+U.sec('Đo lường hiệu quả','Lượt xem · giữ chân · xem hết · chia sẻ · lưu · chuyển đổi')+veDoLuong()+'</div>'+
    '</div>';

    var nv = veNV();
    o += U.sec('Mười nghiệp vụ điều hành xưởng','Bấm ô trạng thái để theo dõi (chưa · đang · xong) · bấm "Mở" để thao tác · đã xong '+nv.xong+'/10');
    o += nv.html;

    o += '<p class="tiny muted" style="margin-top:12px">'+ic('shield','w-3 h-3')+' Màn điều hành này không đụng xưởng dựng video (gói nghề · máy chủ). Trạng thái nghiệp vụ lưu trên máy anh/chị, giữ qua phiên. Mỗi "Mở" vẫn qua cổng quyền của hệ.</p>';
    return o;
  };
})();

})();

/* ═════════ src/studio-lam-phim.js ═════════ */
(function(){
/* ═══════════════════════════════════════════════════════════════
   GITA 365 — CHƯƠNG TRÌNH LÀM PHIM · 10 BƯỚC RA PHIM (Xưởng phim AI)

   Không phải bảng — đây là CHƯƠNG TRÌNH LÀM THEO: đi từ bước 1 đến bước
   10 là có một phim 9:16 hoàn chỉnh. Mỗi bước: mục tiêu · việc cần làm
   (tick được) · GITA Studio AI làm giúp · mẫu nhanh · đầu ra → bước sau.

   Khung chuẩn thật của nghề làm phim; phần AI mô tả đúng cách xưởng dựng
   video đang chạy (sinh tại thiết bị, không gửi máy chủ/dịch vụ ngoài).
   KHÔNG đụng studio.js · máy chủ · giấy phép. View key: lam-phim-10.
   Tick dùng chung gdNV + G.gdTick (khoá riêng lp-*). Mở cho qt_trang.
   ═══════════════════════════════════════════════════════════════ */
'use strict';
var G = window.G || {}; window.G = G; G.VIEWS = G.VIEWS || {};
(function(){
  var U = G.U, h = U.h, ic = U.ic;
  var TTC = { '':'--ink-4', dang:'--warn', xong:'--ok' };

  var STEPS = [
    { ten:'Chọn phim & mục tiêu', muc:'Biết rõ làm phim gì, cho ai, để làm gì — trước khi viết một chữ.',
      viec:['Chọn loại phim (cầu nối · WOW · testimonial · hướng dẫn · quảng cáo)',
            'Chốt 1 thông điệp chính','Ghi đối tượng xem','Chọn lời kêu gọi (CTA)','Chọn độ dài mục tiêu'],
      ai:'GITA gợi ý loại phim & độ dài hợp mục tiêu, mở sẵn brief mẫu để điền nhanh.',
      mau:'<b>Brief 1 trang:</b> “Phim [loại] cho [đối tượng]. Một thông điệp: [___]. CTA: [___]. Độ dài: [___]. Cảm xúc muốn tạo: [___].”',
      out:'Brief 1 trang' },

    { ten:'Viết kịch bản', muc:'Có kịch bản + lời đọc, mở đầu bằng hook 3 giây giữ người xem.',
      viec:['Viết hook 3 giây đầu','Dựng cấu trúc 8 phần','Viết lời đọc tự nhiên, đúng giọng GITA','Chốt CTA ở cuối'],
      ai:'Studio sinh kịch bản từ <b>Ngân khố câu</b> theo brief — ngay tại thiết bị, lời không gửi lên máy chủ.',
      mau:'<b>8 phần:</b> Hook → Vấn đề → Đồng cảm → Giải pháp → Bằng chứng → Hướng dẫn → Kết quả → CTA.',
      out:'Kịch bản + lời đọc' },

    { ten:'Storyboard & shot list', muc:'Thấy trước từng cảnh, dựng theo khung dọc 9:16.',
      viec:['Chia cảnh theo kịch bản','Phác khung hình 9:16 từng cảnh','Ghi shot list','Đánh dấu cảnh quay vs cảnh dựng'],
      ai:'Studio tự tách cảnh từ kịch bản và gợi bố cục khung 9:16 cho mỗi cảnh.',
      mau:'<b>Mỗi dòng shot:</b> [số cảnh] · [nội dung hình] · [lời/chữ trên hình] · [thời lượng].',
      out:'Storyboard + shot list' },

    { ten:'Chuẩn bị vật liệu', muc:'Gom đủ hình · giọng · nhạc · chữ trước khi dựng, không thiếu giữa chừng.',
      viec:['Chọn giọng đọc (mẫu tham chiếu tại máy)','Chọn nhạc nền có bản quyền từ kho','Gom hình / tư liệu (b-roll)','Chuẩn bị phụ đề','Mở brand kit (logo · màu · font)'],
      ai:'Studio dựng hình canvas 1080p, giọng tham chiếu và phối nhạc <b>ngay trên thiết bị</b> — không tải ảnh/giọng lên dịch vụ ngoài.',
      out:'Bộ vật liệu đủ để dựng' },

    { ten:'Dựng hình từng cảnh', muc:'Biến mỗi cảnh trong storyboard thành hình động 9:16.',
      viec:['Dựng từng cảnh theo storyboard','Thêm chuyển động máy quay','Áp màu phim','Canh thời lượng mỗi cảnh'],
      ai:'Studio dựng cảnh, chuyển động và màu phim theo shot list đã nạp.',
      out:'Các cảnh đã dựng' },

    { ten:'Ghép bản thô (rough cut)', muc:'Thấy phim chạy đủ từ đầu đến cuối, chốt mạch kể.',
      viec:['Ghép các cảnh theo đúng thứ tự','Canh nhịp & tổng thời lượng','Xem lại toàn mạch, cắt chỗ thừa'],
      ai:'Studio ghép theo thứ tự kịch bản và báo nếu tổng thời lượng vượt mục tiêu.',
      out:'Bản dựng thô' },

    { ten:'Hoàn thiện (dựng tinh)', muc:'Phim sạch, đẹp, nghe rõ, có phụ đề, đúng thương hiệu.',
      viec:['Chỉnh màu phim','Mix âm thanh & chuẩn âm lượng','Phối nhạc nền','Gắn phụ đề','Thêm motion / đồ hoạ & logo'],
      ai:'Studio xử lý màu · âm · phụ đề · motion tại thiết bị; nhạc lấy từ kho bản quyền.',
      out:'Bản phim hoàn chỉnh' },

    { ten:'Soát & duyệt', muc:'Đạt chuẩn và an toàn trước khi ra mắt — không sửa sau khi đã đăng.',
      viec:['Soát checklist chuẩn 9:16','Soát nhận diện thương hiệu','Soát pháp lý & bản quyền nhạc/hình','Ẩn danh dữ liệu khách (theo hiến pháp)','Duyệt cuối'],
      ai:'Studio soát ngôn từ qua cổng duyệt nội dung của hệ; dữ liệu khách không bị gửi đi.',
      out:'Bản đã duyệt' },

    { ten:'Xuất & phát hành', muc:'Phim lên kênh đúng định dạng, đúng lịch, có đường đo.',
      viec:['Xuất 9:16 (1080×1920)','Viết tiêu đề & mô tả','Đặt lịch đăng','Gắn liên kết đo lường','Đăng lên kênh'],
      ai:'Studio xuất đúng định dạng dọc và gợi khung tiêu đề/mô tả theo loại phim.',
      out:'Video đã phát hành' },

    { ten:'Đo lường & lặp lại', muc:'Học từ số liệu để phim sau tốt hơn — vòng lặp không dừng.',
      viec:['Theo dõi lượt xem & giữ chân 3 giây','Đo % xem hết','Đo chia sẻ · lưu · chuyển đổi','Ghi bài học','Đưa bài học vào brief phim kế tiếp'],
      ai:'Studio tổng hợp “thẻ kết quả” mỗi phim để so sánh và chỉ ra bước nào cần cải thiện.',
      out:'Thẻ kết quả + bài học → quay lại Bước 1' }
  ];

  function demXong(){
    var nv = G.S.gdNV || {}, xong=0, tong=0;
    STEPS.forEach(function(s,si){ s.viec.forEach(function(_,i){ tong++; if(nv['lp-'+si+':'+i]==='xong') xong++; }); });
    return {xong:xong, tong:tong};
  }

  function veStep(s, si){
    var nv = G.S.gdNV || {};
    var xongBuoc = s.viec.every(function(_,i){ return nv['lp-'+si+':'+i]==='xong'; });
    var checks = s.viec.map(function(v,i){
      var id='lp-'+si+':'+i; var st=nv[id]||''; var c=TTC[st];
      return '<div class="lp-check'+(st==='xong'?' x':'')+'">'+
        '<button class="gd-tick gd-tick-'+(st||'chua')+'" data-gdtick="'+h(id)+'" style="--m:var('+c+')" title="Bấm đổi trạng thái">'+
          (st==='xong'?ic('check','w-3 h-3'):st==='dang'?ic('clock','w-3 h-3'):'')+'</button>'+
        '<span class="lp-ct">'+h(v)+'</span></div>';
    }).join('');
    var mau = s.mau ? '<div class="lp-sub">Mẫu nhanh</div><div class="lp-mau">'+s.mau+'</div>' : '';
    return '<div class="lp-step'+(xongBuoc?' done':'')+'">'+
      '<div class="lp-head"><span class="lp-num">'+(si+1)+'</span>'+
        '<div><div class="lp-tt">'+h(s.ten)+'</div><div class="lp-goal">'+h(s.muc)+'</div></div></div>'+
      '<div class="lp-sub">Việc cần làm</div>'+checks+
      '<div class="lp-sub">GITA Studio AI làm giúp</div><div class="lp-ai">'+ic('spark','w-4 h-4')+'<span>'+s.ai+'</span></div>'+
      mau+
      '<div class="lp-out">'+ic('arrow','w-3 h-3')+'Đầu ra: '+h(s.out)+'</div>'+
    '</div>';
  }

  G.VIEWS['lam-phim-10'] = function(){
    if(!(typeof G.can==='function' && G.can('qt_trang')))
      return U.lockCard('Chương trình làm phim mở cho Super Admin / Admin. Đăng nhập đúng vai để xem.');

    var d = demXong(); var pct = d.tong? Math.round(d.xong*100/d.tong):0;
    var buocXong = STEPS.filter(function(s,si){ return s.viec.every(function(_,i){ return (G.S.gdNV||{})['lp-'+si+':'+i]==='xong'; }); }).length;

    var o = U.ph({ eyebrow:'XƯỞNG PHIM AI · LÀM THEO LÀ RA PHIM', ic:'sparkle', grad:1,
      t:'Chương trình làm phim — 10 bước ra phim',
      lead:'Không phải bảng tra cứu — đây là chương trình làm theo. Đi lần lượt từ Bước 1 đến Bước 10 là có một phim 9:16 hoàn chỉnh. Mỗi bước có việc cần làm (tick khi xong), phần GITA Studio AI làm giúp, mẫu nhanh và đầu ra nối sang bước sau.' });

    o += '<div class="row mb" style="gap:8px;flex-wrap:wrap">'+
      '<button class="btn ghost sm" data-v="studio-he">'+ic('arrow','w-3 h-3')+'Hệ điều hành xưởng</button>'+
      '<button class="btn sm" data-v="ban-dung">'+ic('tools','w-3 h-3')+'Bàn dựng (biên tập tại máy)</button>'+
      (G.allowed && G.allowed('studio') ? '<button class="btn ghost sm" data-v="studio">'+ic('spark','w-3 h-3')+'Mở xưởng dựng video</button>' : '')+
      '</div>';

    o += '<div class="lp-prog"><div class="lp-prog-bar"><div class="lp-prog-fill" style="width:'+pct+'%"></div></div>'+
      '<span class="lp-prog-txt">'+buocXong+'/10 bước xong · '+d.xong+'/'+d.tong+' việc</span></div>';

    o += STEPS.map(veStep).join('');

    o += '<p class="tiny muted" style="margin-top:12px">'+ic('shield','w-3 h-3')+' Tick việc lưu trên máy anh/chị, giữ qua phiên — làm tới đâu nhớ tới đó. Phần AI dựng ngay tại thiết bị, không gửi hình/giọng/dữ liệu khách ra ngoài. Màn này không đụng xưởng dựng video (gói nghề · máy chủ).</p>';
    return o;
  };
})();

})();

/* ═════════ src/studio-ban-dung.js ═════════ */
(function(){
/* ═══════════════════════════════════════════════════════════════
   GITA 365 — BÀN DỰNG STUDIO · biên tập ảnh · màu · hiệu ứng · chữ ·
   âm thanh · ghép ảnh thành phim  (xưởng sản xuất toàn diện, TẠI MÁY)

   Công cụ biên tập THẬT, chạy hoàn toàn trên thiết bị bằng Canvas 2D +
   Web Audio + MediaRecorder — KHÔNG gửi ảnh/giọng/dữ liệu ra máy chủ hay
   dịch vụ ngoài (đúng luật xưởng). KHÔNG đụng studio.js (xưởng dựng video
   gói nghề) · máy chủ · giấy phép. View key: ban-dung. Mở cho qt_trang.

   Làm được:
     · Nạp & ghép nhiều ảnh, khung dọc 9:16, phóng·di·xoay·lật
     · Chỉnh sáng · tương phản · bão hoà · ấm/lạnh · mờ · nét · tối góc
     · Hiệu ứng điện ảnh (preset lọc màu)
     · Thêm chữ (tiêu đề·phụ đề) + logo GITA
     · Ghép nhạc nền + giọng đọc, chỉnh âm lượng & fade, nghe thử
     · Ghép các khung thành phim (slideshow) + nhạc/giọng → xem thử
     · Xuất khung ảnh PNG · xuất video nháp (.webm) nếu trình duyệt hỗ trợ
   ═══════════════════════════════════════════════════════════════ */
'use strict';
var G = window.G || {}; window.G = G; G.VIEWS = G.VIEWS || {};
(function(){
  var U = G.U, h = U.h, ic = U.ic;
  var W = 1080, H = 1920;

  var PRESET = {
    ''        : { ten:'Gốc',       sang:100, tuong:100, bao:100, am:0,   vig:0,  sepia:0,  gray:0  },
    dienanh   : { ten:'Điện ảnh',  sang:100, tuong:116, bao:92,  am:-8,  vig:38, sepia:6,  gray:0  },
    am        : { ten:'Ấm áp',     sang:104, tuong:102, bao:110, am:30,  vig:10, sepia:8,  gray:0  },
    lanh      : { ten:'Lạnh',      sang:100, tuong:107, bao:96,  am:-28, vig:12, sepia:0,  gray:0  },
    bw        : { ten:'Đen trắng', sang:102, tuong:114, bao:100, am:0,   vig:24, sepia:0,  gray:100},
    codien    : { ten:'Cổ điển',   sang:101, tuong:98,  bao:88,  am:14,  vig:32, sepia:48, gray:0  },
    rucro     : { ten:'Rực rỡ',    sang:103, tuong:109, bao:138, am:4,   vig:0,  sepia:0,  gray:0  }
  };

  /* Trạng thái sống (ảnh/âm là bộ nhớ phiên, không serialize vào G.S) */
  var S = G.bdS = G.bdS || {
    anh:[], hoat:-1, fit:'cover', zoom:1, offX:0, offY:0, rot:0, flip:false,
    sang:100, tuong:100, bao:100, am:0, mo:0, net:0, vig:0, sepia:0, gray:0, preset:'',
    tieuDe:'', phuDe:'', cuChu:70, mauChu:'#ffffff', viChu:'duoi', logo:true, viLogo:'phai',
    nhac:null, nhacTen:'', giong:null, giongTen:'', amNhac:0.45, amGiong:1, fadeIn:true, fadeOut:true,
    khung:[], moiKhung:2.5, chuyen:'mo'
  };
  var AC=null, nut=[], choi=false, raf=0, ghiMR=null;
  function ac(){ return (AC = AC || new (window.AudioContext||window.webkitAudioContext)()); }
  function cv(){ return document.getElementById('bd-cv'); }
  function ctx(){ var c=cv(); return c?c.getContext('2d'):null; }

  /* ════════ VẼ KHUNG ════════ */
  function veKhung(c, bo){
    if(!c) return;
    var x = c.getContext('2d');
    x.save(); x.setTransform(1,0,0,1,0,0);
    x.fillStyle = '#0c1118'; x.fillRect(0,0,W,H);

    var img = S.anh[S.hoat];
    x.filter = 'brightness('+S.sang+'%) contrast('+S.tuong+'%) saturate('+S.bao+'%) blur('+S.mo+'px)'+
               (S.sepia?' sepia('+S.sepia+'%)':'') + (S.gray?' grayscale('+S.gray+'%)':'');
    if(img){
      var iw=img.width, ih=img.height, s;
      if(S.fit==='cover') s = Math.max(W/iw, H/ih); else s = Math.min(W/iw, H/ih);
      s *= S.zoom;
      var dw=iw*s, dh=ih*s;
      x.translate(W/2 + S.offX, H/2 + S.offY);
      x.rotate(S.rot*Math.PI/180);
      x.scale(S.flip?-1:1, 1);
      x.drawImage(img, -dw/2, -dh/2, dw, dh);
    } else {
      /* Chưa nạp ảnh — nền chuyển sắc để vẫn dựng chữ/âm được */
      var g = x.createLinearGradient(0,0,0,H);
      g.addColorStop(0,'#1b2b4d'); g.addColorStop(1,'#0c1118');
      x.filter='none'; x.fillStyle=g; x.fillRect(0,0,W,H);
    }
    x.restore();
    x.filter='none';

    /* Ấm / lạnh — phủ một lớp màu mỏng */
    if(S.am){
      x.save(); x.globalCompositeOperation='soft-light';
      x.globalAlpha = Math.min(Math.abs(S.am)/100*0.9, 0.6);
      x.fillStyle = S.am>0 ? '#ff8a1e' : '#1e7bff';
      x.fillRect(0,0,W,H); x.restore();
    }
    /* Tối góc (vignette) */
    if(S.vig){
      x.save();
      var r = x.createRadialGradient(W/2,H/2,H*0.30, W/2,H/2,H*0.72);
      r.addColorStop(0,'rgba(0,0,0,0)'); r.addColorStop(1,'rgba(0,0,0,'+(S.vig/100*0.85)+')');
      x.fillStyle=r; x.fillRect(0,0,W,H); x.restore();
    }
    if(!bo || !bo.khongChu) veChuLogo(x);
  }
  function veChuLogo(x){
    if(S.tieuDe || S.phuDe){
      var y = S.viChu==='tren' ? H*0.16 : S.viChu==='giua' ? H*0.50 : H*0.82;
      x.save(); x.textAlign='center'; x.shadowColor='rgba(0,0,0,.6)'; x.shadowBlur=18; x.shadowOffsetY=3;
      x.fillStyle=S.mauChu;
      if(S.tieuDe){ x.font='800 '+S.cuChu+'px "Be Vietnam Pro",system-ui,sans-serif';
        wrapText(x, S.tieuDe, W/2, y, W*0.86, S.cuChu*1.14); }
      if(S.phuDe){ x.font='500 '+Math.round(S.cuChu*0.56)+'px "Be Vietnam Pro",system-ui,sans-serif';
        var yp = y + (S.tieuDe? S.cuChu*1.25 : 0);
        wrapText(x, S.phuDe, W/2, yp, W*0.82, S.cuChu*0.70); }
      x.restore();
    }
    if(S.logo){
      var pad=46, bw=250, bh=74, bx = S.viLogo==='trai'?pad:(W-bw-pad), by=pad;
      x.save(); x.globalAlpha=0.92;
      roundRect(x, bx, by, bw, bh, 16); x.fillStyle='rgba(10,20,40,.55)'; x.fill();
      x.fillStyle='#fff'; x.textAlign='left'; x.font='800 40px "Be Vietnam Pro",system-ui,sans-serif';
      x.fillText('GITA', bx+22, by+50);
      x.fillStyle='#8fb6ff'; x.font='700 24px "Be Vietnam Pro",system-ui,sans-serif';
      x.fillText('365', bx+140, by+49); x.restore();
    }
  }
  function wrapText(x,t,cx,cy,maxW,lh){
    var words=String(t).split(/\s+/), line='', lines=[];
    words.forEach(function(w){ var test=line?line+' '+w:w;
      if(x.measureText(test).width>maxW && line){ lines.push(line); line=w; } else line=test; });
    if(line) lines.push(line);
    var y0 = cy - (lines.length-1)*lh/2;
    lines.forEach(function(l,i){ x.fillText(l, cx, y0+i*lh); });
  }
  function roundRect(x,rx,ry,rw,rh,r){ x.beginPath();
    x.moveTo(rx+r,ry); x.arcTo(rx+rw,ry,rx+rw,ry+rh,r); x.arcTo(rx+rw,ry+rh,rx,ry+rh,r);
    x.arcTo(rx,ry+rh,rx,ry,r); x.arcTo(rx,ry,rx+rw,ry,r); x.closePath(); }

  function ve(){ veKhung(cv()); }
  G.bd = G.bd || {};
  G.bd.init = function(){ var c=cv(); if(!c) return; c.width=W; c.height=H; ve(); veStrip(); };

  /* ════════ ĐIỀU KHIỂN ════════ */
  G.bd.set = function(k,v){
    if(k==='fit'||k==='viChu'||k==='viLogo'||k==='chuyen'||k==='mauChu'||k==='tieuDe'||k==='phuDe') S[k]=v;
    else if(k==='flip'||k==='logo') S[k]=!S[k];
    else S[k]=+v;
    var el=document.getElementById('bdv-'+k); if(el) el.textContent = v;
    ve();
    if(k==='flip'||k==='logo'||k==='viChu'||k==='viLogo'||k==='fit'||k==='mauChu') dongBo();
  };
  function dongBo(){ /* cập nhật nút segment on/off mà không re-render cả màn */
    ['fit','viChu','viLogo','chuyen'].forEach(function(g){
      var box=document.getElementById('seg-'+g); if(!box) return;
      Array.prototype.forEach.call(box.querySelectorAll('button'), function(b){
        b.classList.toggle('on', b.getAttribute('data-v')===String(S[g])); });
    });
    var lg=document.getElementById('bd-logo-btn'); if(lg) lg.classList.toggle('on', S.logo);
    var fl=document.getElementById('bd-flip-btn'); if(fl) fl.classList.toggle('on', S.flip);
  }
  G.bd.preset = function(p){
    var P=PRESET[p]||PRESET['']; S.preset=p;
    S.sang=P.sang; S.tuong=P.tuong; S.bao=P.bao; S.am=P.am; S.vig=P.vig; S.sepia=P.sepia; S.gray=P.gray;
    ['sang','tuong','bao','am','vig'].forEach(function(k){
      var r=document.getElementById('bdr-'+k); if(r) r.value=S[k];
      var t=document.getElementById('bdv-'+k); if(t) t.textContent=S[k];
    });
    Array.prototype.forEach.call(document.querySelectorAll('.bd-ps'), function(b){
      b.classList.toggle('on', b.getAttribute('data-p')===p); });
    ve();
  };
  G.bd.reset = function(){ S.zoom=1;S.offX=0;S.offY=0;S.rot=0;S.flip=false; G.bd.preset(''); dongBo();
    ['zoom','rot'].forEach(function(k){var r=document.getElementById('bdr-'+k);if(r)r.value=S[k];var t=document.getElementById('bdv-'+k);if(t)t.textContent=S[k];});
    ve(); };

  /* ════════ NẠP VẬT LIỆU (tại máy) ════════ */
  G.bd.napAnh = function(inp){
    var fs=inp.files; if(!fs||!fs.length) return;
    Array.prototype.forEach.call(fs, function(f){
      if(!/^image\//.test(f.type)) return;
      createImageBitmap(f).then(function(bm){ S.anh.push(bm); S.hoat=S.anh.length-1; ve(); G.bd.dsAnh(); })
        .catch(function(){ U.toast('Không đọc được ảnh "'+f.name+'".','err'); });
    });
    inp.value='';
  };
  G.bd.chonAnh = function(i){ S.hoat=i; ve(); G.bd.dsAnh(); };
  G.bd.xoaAnh = function(i){ S.anh.splice(i,1); if(S.hoat>=S.anh.length) S.hoat=S.anh.length-1; ve(); G.bd.dsAnh(); };
  G.bd.dsAnh = function(){
    var box=document.getElementById('bd-ds-anh'); if(!box) return;
    if(!S.anh.length){ box.innerHTML='<p class="bd-tip">Chưa có ảnh. Nạp ảnh để bắt đầu dựng khung.</p>'; return; }
    box.innerHTML = S.anh.map(function(_,i){
      return '<div class="bd-chip" style="cursor:pointer'+(i===S.hoat?';border-color:var(--gita);color:var(--gita)':'')+'" '+
        'onclick="G.bd.chonAnh('+i+')">Ảnh '+(i+1)+' <b onclick="event.stopPropagation();G.bd.xoaAnh('+i+')" style="cursor:pointer;color:var(--gita-do-ink)">✕</b></div>';
    }).join('');
  };

  G.bd.napNhac = function(inp){ var f=inp.files[0]; if(!f) return;
    f.arrayBuffer().then(function(b){return ac().decodeAudioData(b);})
      .then(function(buf){ S.nhac=buf; S.nhacTen=f.name;
        var el=document.getElementById('bd-nhac-ten'); if(el) el.textContent=f.name+' · '+buf.duration.toFixed(1)+'s';
        U.toast('Đã nạp nhạc nền.','ok'); })
      .catch(function(){ U.toast('Không đọc được nhạc.','err'); }); inp.value=''; };
  G.bd.napGiong = function(inp){ var f=inp.files[0]; if(!f) return;
    f.arrayBuffer().then(function(b){return ac().decodeAudioData(b);})
      .then(function(buf){ S.giong=buf; S.giongTen=f.name;
        var el=document.getElementById('bd-giong-ten'); if(el) el.textContent=f.name+' · '+buf.duration.toFixed(1)+'s';
        U.toast('Đã nạp giọng đọc.','ok'); })
      .catch(function(){ U.toast('Không đọc được giọng.','err'); }); inp.value=''; };

  /* ════════ ÂM THANH — nghe thử bản phối ════════ */
  function dungTieng(){ nut.forEach(function(n){try{n.stop();}catch(e){}}); nut=[]; }
  function xepTieng(dich, dur){
    var a=ac(), t0=a.currentTime+0.06;
    [['nhac',S.amNhac],['giong',S.amGiong]].forEach(function(p){
      var buf=S[p[0]]; if(!buf) return;
      var src=a.createBufferSource(), g=a.createGain();
      src.buffer=buf; if(p[0]==='nhac') src.loop=true;
      g.gain.value=p[1];
      if(S.fadeIn){ g.gain.setValueAtTime(0.0001,t0); g.gain.exponentialRampToValueAtTime(Math.max(p[1],0.001),t0+0.8); }
      if(S.fadeOut && dur){ g.gain.setValueAtTime(Math.max(p[1],0.001),t0+Math.max(dur-0.9,0.01)); g.gain.exponentialRampToValueAtTime(0.0001,t0+dur); }
      src.connect(g); g.connect(dich); src.start(t0); nut.push(src);
    });
  }
  G.bd.ngheAm = function(){
    if(!S.nhac && !S.giong){ U.toast('Chưa có nhạc hay giọng để nghe.','err'); return; }
    ac().resume(); dungTieng();
    var dur = Math.max(S.giong?S.giong.duration:0, S.nhac?Math.min(S.nhac.duration,20):0, 3);
    xepTieng(ac().destination, dur);
    U.toast('Đang nghe thử bản phối…','ok');
  };
  G.bd.dungAm = function(){ dungTieng(); };

  /* ════════ GHÉP PHIM (slideshow) ════════ */
  G.bd.themKhung = function(){
    var url = cv().toDataURL('image/png');
    var im = new Image(); im.src=url;
    S.khung.push({url:url, giay:S.moiKhung, img:im}); veStrip();
    U.toast('Đã thêm khung '+S.khung.length+' vào phim.','ok');
  };
  G.bd.xoaKhung = function(i){ S.khung.splice(i,1); veStrip(); };
  function veStrip(){
    var box=document.getElementById('bd-strip'); if(!box) return;
    if(!S.khung.length){ box.innerHTML='<p class="bd-tip">Chưa có khung nào. Dựng một khung rồi bấm “Thêm khung vào phim”.</p>'; return; }
    box.innerHTML = S.khung.map(function(k,i){
      return '<div style="position:relative;flex:none"><img class="bd-frame" src="'+k.url+'" title="Khung '+(i+1)+'">'+
        '<b onclick="G.bd.xoaKhung('+i+')" style="position:absolute;top:2px;right:2px;background:#000a;color:#fff;border-radius:50%;width:18px;height:18px;display:grid;place-items:center;font-size:11px;cursor:pointer">✕</b>'+
        '<span style="position:absolute;bottom:2px;left:2px;background:#000a;color:#fff;font-size:9px;padding:1px 4px;border-radius:4px">'+(i+1)+'</span></div>';
    }).join('');
  }
  function tongGiay(){ return S.khung.reduce(function(s,k){return s+(+k.giay||0);},0); }

  G.bd.xemPhim = function(){
    if(!S.khung.length){ U.toast('Chưa có khung nào để chiếu.','err'); return; }
    var c=cv(), x=c.getContext('2d'); choi=true;
    ac().resume(); dungTieng(); xepTieng(ac().destination, tongGiay());
    var t0=performance.now();
    function nhip(now){
      if(!choi) return;
      var t=(now-t0)/1000, acc=0, idx=0, inner=0;
      for(var i=0;i<S.khung.length;i++){ var g=+S.khung[i].giay||0.1; if(t<acc+g){idx=i;inner=(t-acc)/g;break;} acc+=g; idx=i; inner=1; }
      if(t>=tongGiay()){ choi=false; dungTieng(); veStrip(); return; }
      var k=S.khung[idx];
      if(k.img && k.img.complete){ x.drawImage(k.img,0,0,W,H);
        if(S.chuyen==='mo' && inner<0.18){ x.save(); x.globalAlpha=1-inner/0.18; x.fillStyle='#000'; x.fillRect(0,0,W,H); x.restore(); } }
      raf=requestAnimationFrame(nhip);
    }
    raf=requestAnimationFrame(nhip);
  };
  G.bd.dungPhim = function(){ choi=false; cancelAnimationFrame(raf); dungTieng(); ve(); };

  /* ════════ XUẤT ════════ */
  G.bd.xuatPNG = function(){
    try{ var a=document.createElement('a'); a.download='gita-khung-'+Date.now()+'.png';
      a.href=cv().toDataURL('image/png'); a.click(); U.toast('Đã xuất khung ảnh PNG.','ok'); }
    catch(e){ U.toast('Không xuất được ảnh: '+(e&&e.message),'err'); }
  };
  G.bd.xuatVideo = function(){
    if(!S.khung.length){ U.toast('Cần ít nhất một khung để xuất phim.','err'); return; }
    var c=cv();
    if(!c.captureStream || typeof MediaRecorder==='undefined'){
      U.toast('Trình duyệt này chưa hỗ trợ xuất video. Dùng Chrome/Edge mới, hoặc xuất từng khung PNG.','err'); return; }
    try{
      var vs=c.captureStream(30), dest=ac().createMediaStreamDestination();
      var tracks=vs.getVideoTracks().concat(dest.stream.getAudioTracks());
      var st=new MediaStream(tracks);
      var mime = MediaRecorder.isTypeSupported('video/webm;codecs=vp9')?'video/webm;codecs=vp9':'video/webm';
      var mr=new MediaRecorder(st,{mimeType:mime}), manh=[];
      ghiMR=mr;
      mr.ondataavailable=function(e){ if(e.data.size) manh.push(e.data); };
      mr.onstop=function(){
        var bl=new Blob(manh,{type:mime}); var fr=new FileReader();
        fr.onload=function(){ var a=document.createElement('a'); a.download='gita-phim-'+Date.now()+'.webm'; a.href=fr.result; a.click();
          U.toast('Đã xuất video nháp (.webm).','ok'); };
        fr.readAsDataURL(bl); ghiMR=null;
      };
      /* chạy slideshow + ghi đồng thời */
      choi=true; var x=c.getContext('2d'), t0=performance.now();
      dungTieng(); xepTieng(dest, tongGiay());
      mr.start();
      U.toast('Đang dựng video… giữ màn hình tới khi xong.','ok');
      function nhip(now){
        if(!choi){ return; }
        var t=(now-t0)/1000, acc=0, idx=0;
        for(var i=0;i<S.khung.length;i++){ var g=+S.khung[i].giay||0.1; if(t<acc+g){idx=i;break;} acc+=g; idx=i; }
        if(t>=tongGiay()){ choi=false; try{mr.stop();}catch(e){} dungTieng(); ve(); veStrip(); return; }
        var k=S.khung[idx]; if(k.img&&k.img.complete) x.drawImage(k.img,0,0,W,H);
        raf=requestAnimationFrame(nhip);
      }
      raf=requestAnimationFrame(nhip);
    }catch(e){ U.toast('Không xuất được video: '+(e&&e.message),'err'); }
  };

  /* ════════ GIAO DIỆN ════════ */
  function slider(k,lbl,mn,mx,unit){
    return '<div class="bd-row"><span class="bd-lbl">'+h(lbl)+'</span>'+
      '<input type="range" id="bdr-'+k+'" min="'+mn+'" max="'+mx+'" value="'+S[k]+'" oninput="G.bd.set(\''+k+'\',this.value)">'+
      '<span class="bd-val"><span id="bdv-'+k+'">'+S[k]+'</span>'+(unit||'')+'</span></div>';
  }
  function seg(k,opts){
    return '<div class="bd-seg" id="seg-'+k+'">'+ opts.map(function(o){
      return '<button data-v="'+o[0]+'" class="'+(String(S[k])===o[0]?'on':'')+'" onclick="G.bd.set(\''+k+'\',\''+o[0]+'\')">'+h(o[1])+'</button>';
    }).join('') +'</div>';
  }

  G.VIEWS['ban-dung'] = function(){
    if(!(typeof G.can==='function' && G.can('qt_trang')))
      return U.lockCard('Bàn dựng Studio mở cho Super Admin / Admin. Đăng nhập đúng vai để xem.');

    var o = U.ph({ eyebrow:'XƯỞNG PHIM · BÀN DỰNG TẠI MÁY', ic:'sparkle', grad:1,
      t:'Bàn dựng GITA Studio',
      lead:'Biên tập thật ngay trên thiết bị: nạp & ghép ảnh, chỉnh sáng·màu·hiệu ứng, thêm chữ & logo, ghép nhạc + giọng, rồi ghép các khung thành phim 9:16 và xuất ra. Không gửi ảnh·giọng·dữ liệu ra ngoài.' });

    o += '<div class="row mb" style="gap:8px;flex-wrap:wrap">'+
      '<button class="btn ghost sm" data-v="studio-he">'+ic('arrow','w-3 h-3')+'Hệ điều hành xưởng</button>'+
      '<button class="btn ghost sm" data-v="lam-phim-10">'+ic('sparkle','w-3 h-3')+'Chương trình 10 bước</button>'+
      (G.allowed && G.allowed('studio') ? '<button class="btn ghost sm" data-v="studio">'+ic('spark','w-3 h-3')+'Xưởng dựng video (gói nghề)</button>' : '')+
      '</div>';

    o += '<div class="bd-wrap">';

    /* CỘT TRÁI · màn xem + xuất */
    o += '<div class="bd-stage">'+
      '<canvas id="bd-cv" class="bd-cv" width="'+W+'" height="'+H+'"></canvas>'+
      '<button class="btn sm" onclick="G.bd.xuatPNG()">'+ic('arrow','w-3 h-3')+'Xuất khung ảnh (PNG)</button>'+
      '<button class="btn ghost sm" onclick="G.bd.reset()">'+ic('orbit','w-3 h-3')+'Đặt lại chỉnh sửa</button>'+
    '</div>';

    /* CỘT PHẢI · bảng điều khiển 6 nhóm (tab CSS) */
    o += '<div class="bd-ctrl">'+
      '<input type="radio" name="bdTab" id="bd-anh" class="bd-radio" checked>'+
      '<input type="radio" name="bdTab" id="bd-mau" class="bd-radio">'+
      '<input type="radio" name="bdTab" id="bd-ht" class="bd-radio">'+
      '<input type="radio" name="bdTab" id="bd-chu" class="bd-radio">'+
      '<input type="radio" name="bdTab" id="bd-am" class="bd-radio">'+
      '<input type="radio" name="bdTab" id="bd-phim" class="bd-radio">'+
      '<div class="bd-tabbar">'+
        '<label for="bd-anh">'+ic('grid','w-3 h-3')+'Ảnh & khung</label>'+
        '<label for="bd-mau">'+ic('pulse','w-3 h-3')+'Sáng & màu</label>'+
        '<label for="bd-ht">'+ic('spark','w-3 h-3')+'Hiệu ứng</label>'+
        '<label for="bd-chu">'+ic('quote','w-3 h-3')+'Chữ & logo</label>'+
        '<label for="bd-am">'+ic('heart','w-3 h-3')+'Âm thanh</label>'+
        '<label for="bd-phim">'+ic('sparkle','w-3 h-3')+'Ghép phim & xuất</label>'+
      '</div>';

    /* 1 · Ảnh & khung */
    o += '<div id="bd-p-anh" class="bd-pan">'+
      '<label class="bd-file">'+ic('arrow','w-3 h-3')+'Nạp ảnh (có thể nhiều)<input type="file" accept="image/*" multiple onchange="G.bd.napAnh(this)"></label>'+
      '<div class="bd-chips" id="bd-ds-anh"><p class="bd-tip">Chưa có ảnh. Nạp ảnh để bắt đầu dựng khung.</p></div>'+
      '<div class="bd-field"><span>Cách lấp khung 9:16</span>'+seg('fit',[['cover','Lấp đầy'],['contain','Vừa khít']])+'</div>'+
      slider('zoom','Phóng to',1,4)+
      slider('rot','Xoay (độ)',-45,45)+
      '<div class="bd-field"><span>Lật ngang</span><div class="bd-seg"><button id="bd-flip-btn" class="'+(S.flip?'on':'')+'" onclick="G.bd.set(\'flip\')">Lật trái–phải</button></div></div>'+
    '</div>';

    /* 2 · Sáng & màu */
    o += '<div id="bd-p-mau" class="bd-pan">'+
      slider('sang','Sáng',20,200,'%')+ slider('tuong','Tương phản',20,200,'%')+
      slider('bao','Bão hoà',0,200,'%')+ slider('am','Ấm / Lạnh',-50,50)+
      slider('mo','Mờ mềm',0,12,'px')+ slider('vig','Tối góc',0,100)+
      '<p class="bd-tip">Kéo "Ấm / Lạnh" sang phải cho tông ấm (nắng), sang trái cho tông lạnh (đêm).</p>'+
    '</div>';

    /* 3 · Hiệu ứng */
    o += '<div id="bd-p-ht" class="bd-pan">'+
      '<p class="bd-tip">Bấm một hiệu ứng để áp bộ lọc màu điện ảnh. Sau đó vẫn tinh chỉnh ở tab “Sáng & màu”.</p>'+
      '<div class="bd-presets">'+ Object.keys(PRESET).map(function(p){
        return '<button class="bd-ps'+(S.preset===p?' on':'')+'" data-p="'+p+'" onclick="G.bd.preset(\''+p+'\')">'+h(PRESET[p].ten)+'</button>';
      }).join('') +'</div>'+
    '</div>';

    /* 4 · Chữ & logo */
    o += '<div id="bd-p-chu" class="bd-pan">'+
      '<div class="bd-field"><span>Tiêu đề trên phim</span><input type="text" value="'+h(S.tieuDe)+'" oninput="G.bd.set(\'tieuDe\',this.value)" placeholder="VD: Gia đình thịnh vượng"></div>'+
      '<div class="bd-field"><span>Phụ đề / dòng nhỏ</span><input type="text" value="'+h(S.phuDe)+'" oninput="G.bd.set(\'phuDe\',this.value)" placeholder="VD: Hành trình 5 tầng cùng GITA"></div>'+
      slider('cuChu','Cỡ chữ',32,160)+
      '<div class="bd-field"><span>Vị trí chữ</span>'+seg('viChu',[['tren','Trên'],['giua','Giữa'],['duoi','Dưới']])+'</div>'+
      '<div class="bd-field"><span>Màu chữ</span>'+seg('mauChu',[['#ffffff','Trắng'],['#ffd34d','Vàng'],['#111111','Đen'],['#8fb6ff','Xanh']])+'</div>'+
      '<div class="bd-field"><span>Logo GITA 365</span><div class="bd-seg"><button id="bd-logo-btn" class="'+(S.logo?'on':'')+'" onclick="G.bd.set(\'logo\')">Hiện logo</button></div>'+seg('viLogo',[['phai','Góc phải'],['trai','Góc trái']])+'</div>'+
    '</div>';

    /* 5 · Âm thanh */
    o += '<div id="bd-p-am" class="bd-pan">'+
      '<label class="bd-file">'+ic('arrow','w-3 h-3')+'Nạp nhạc nền<input type="file" accept="audio/*" onchange="G.bd.napNhac(this)"></label> '+
      '<span class="bd-tip" id="bd-nhac-ten">'+(S.nhacTen?h(S.nhacTen):'chưa có nhạc')+'</span>'+
      '<div style="height:8px"></div>'+
      '<label class="bd-file">'+ic('arrow','w-3 h-3')+'Nạp giọng đọc<input type="file" accept="audio/*" onchange="G.bd.napGiong(this)"></label> '+
      '<span class="bd-tip" id="bd-giong-ten">'+(S.giongTen?h(S.giongTen):'chưa có giọng')+'</span>'+
      slider('amNhac','Âm nhạc',0,1)+ slider('amGiong','Âm giọng',0,1)+
      '<div class="bd-field"><span>Vuốt (fade)</span><div class="bd-seg">'+
        '<button class="'+(S.fadeIn?'on':'')+'" onclick="S.__x=0;window.G.bdS.fadeIn=!window.G.bdS.fadeIn;this.classList.toggle(\'on\')">Mở nhẹ đầu</button>'+
        '<button class="'+(S.fadeOut?'on':'')+'" onclick="window.G.bdS.fadeOut=!window.G.bdS.fadeOut;this.classList.toggle(\'on\')">Tắt nhẹ cuối</button>'+
      '</div></div>'+
      '<div class="row" style="gap:8px;margin-top:8px"><button class="btn sm" onclick="G.bd.ngheAm()">'+ic('spark','w-3 h-3')+'Nghe thử</button>'+
        '<button class="btn ghost sm" onclick="G.bd.dungAm()">Dừng</button></div>'+
      '<p class="bd-tip">Nhạc & giọng xử lý tại máy, không gửi đi đâu.</p>'+
    '</div>';

    /* 6 · Ghép phim & xuất */
    o += '<div id="bd-p-phim" class="bd-pan">'+
      '<div class="bd-field"><span>Thời lượng mỗi khung (giây)</span>'+
        '<input type="range" id="bdr-moiKhung" min="1" max="8" step="0.5" value="'+S.moiKhung+'" oninput="window.G.bdS.moiKhung=+this.value;document.getElementById(\'bdv-moiKhung\').textContent=this.value"> '+
        '<span class="bd-val"><span id="bdv-moiKhung">'+S.moiKhung+'</span>s</span></div>'+
      '<div class="bd-field"><span>Chuyển cảnh</span>'+seg('chuyen',[['mo','Mờ dần'],['cat','Cắt thẳng']])+'</div>'+
      '<button class="btn sm" onclick="G.bd.themKhung()">'+ic('check','w-3 h-3')+'Thêm khung hiện tại vào phim</button>'+
      '<div class="bd-strip" id="bd-strip" style="margin-top:10px"><p class="bd-tip">Chưa có khung nào. Dựng một khung rồi bấm “Thêm khung vào phim”.</p></div>'+
      '<div class="row" style="gap:8px;margin-top:6px;flex-wrap:wrap">'+
        '<button class="btn sm" onclick="G.bd.xemPhim()">'+ic('spark','w-3 h-3')+'Xem thử phim</button>'+
        '<button class="btn ghost sm" onclick="G.bd.dungPhim()">Dừng</button>'+
        '<button class="btn" onclick="G.bd.xuatVideo()">'+ic('arrow','w-3 h-3')+'Xuất video (.webm)</button>'+
      '</div>'+
      '<p class="bd-tip">Phim = các khung đã dựng + nhạc/giọng đã nạp. Xuất video chạy ngay trên máy (cần Chrome/Edge mới). Mỗi khung thêm là ảnh PNG của màn hiện tại — chỉnh khung trước, rồi “Thêm”.</p>'+
    '</div>';

    o += '</div></div>'; /* /bd-ctrl /bd-wrap */

    o += '<p class="tiny muted" style="margin-top:14px">'+ic('shield','w-3 h-3')+' Toàn bộ biên tập chạy trong trình duyệt trên máy anh/chị — ảnh, giọng, nhạc KHÔNG tải lên máy chủ hay dịch vụ ngoài. Màn này độc lập, không đụng xưởng dựng video gói nghề.</p>';

    setTimeout(function(){ try{ G.bd.init(); G.bd.dsAnh(); }catch(e){} }, 0);
    return o;
  };
})();

})();

/* ═════════ src/kho-phim-drive.js ═════════ */
(function(){
/* ═══════════════════════════════════════════════════════════════
   GITA 365 · XƯỞNG PHIM — KHO PHIM TRÊN GOOGLE DRIVE (gói 2TB của chủ hệ)

   Mọi phim của hệ thống nằm trong Drive: "GITA365 · Kho phim/Phim/<năm-tháng>/".
   Màn này đọc kho qua Web app Apps Script riêng (xuong-phim-ai/kho-drive/), chạy bằng
   chính tài khoản Drive của chủ hệ — không qua dịch vụ trả phí nào.
     · đồng hồ dung lượng Drive · danh sách phim · xem ngay (trình xem Drive)
     · bật/tắt chia sẻ link · chép link · bỏ vào Thùng rác (giữ 30 ngày)
   Phim làm ở đâu (máy dựng, điện thoại…) cứ kéo vào thư mục Phim trên Drive là màn này thấy.
   Trình duyệt chỉ giữ địa chỉ Web app + KHOA_APP (localStorage). G.khoDrive dùng chung cho
   màn "Làm phim nhanh" (đường miễn phí). View con của san-xuat-ai, tab "Kho phim".
   ═══════════════════════════════════════════════════════════════ */
'use strict';
var G = window.G || {}; window.G = G;
(function(){
  var U = G.U, h = U.h;
  function lsGet(k){ try{ return window.localStorage.getItem(k)||''; }catch(e){ return ''; } }
  function lsSet(k,v){ try{ window.localStorage.setItem(k,v); }catch(e){} }

  var kd = G.khoDrive = G.khoDrive || {};
  kd.cfg = function(){ return { url: lsGet('axDriveUrl'), khoa: lsGet('axDriveKhoa') }; };
  kd.coKho = function(){ var c=kd.cfg(); return !!(c.url && c.khoa); };
  kd.goi = function(viec, data){
    var c = kd.cfg();
    if(!c.url || !c.khoa) return Promise.reject(new Error('Chưa nối kho Drive — mở "Cài đặt kho" ở tab Kho phim.'));
    var than = Object.assign({ khoa:c.khoa, viec:viec }, data||{});
    return fetch(c.url, { method:'POST', headers:{'Content-Type':'text/plain;charset=utf-8'}, body:JSON.stringify(than) })
      .then(function(r){ return r.json(); })
      .then(function(d){ if(d && d.loi) throw new Error(d.loi); return d; });
  };
  kd.xem = function(id){ return 'https://drive.google.com/file/d/'+encodeURIComponent(id)+'/preview'; };
  kd.link = function(id){ return 'https://drive.google.com/file/d/'+encodeURIComponent(id)+'/view'; };

  var st = { phim:null, dung:null, loi:'', dangTai:false, xem:'' };
  function ve(){ if(G.render) G.render(); }
  function gb(b){ return (b/1e9).toLocaleString('vi-VN',{maximumFractionDigits:1})+' GB'; }
  function mb(b){ return b>=1e9 ? gb(b) : Math.max(1,Math.round(b/1e6))+' MB'; }

  kd.tai = function(){
    if(!kd.coKho() || st.dangTai) return;
    st.dangTai=true; st.loi=''; ve();
    Promise.all([kd.goi('kiemTra'), kd.goi('danhSach')]).then(function(kq){
      st.dung = kq[0]; st.phim = kq[1].phim||[]; st.dangTai=false; ve();
    }).catch(function(e){ st.loi=e.message||String(e); st.dangTai=false; ve(); });
  };
  kd.luuCaiDat = function(){
    var u=((document.getElementById('kd-url')||{}).value||'').trim(), k=((document.getElementById('kd-khoa')||{}).value||'').trim();
    if(!/^https:\/\/script\.google\.com\/macros\/s\/[A-Za-z0-9_-]+\/exec$/.test(u)) return U.toast('Địa chỉ phải dạng https://script.google.com/macros/s/…/exec','err');
    if(k.length<24) return U.toast('KHOA_APP chưa đúng (chuỗi dài in ra khi chạy caiDat).','err');
    lsSet('axDriveUrl',u); lsSet('axDriveKhoa',k); st.phim=null; U.toast('Đã nối kho Drive trên máy này.','ok'); kd.tai();
  };
  kd.moXem = function(id){ st.xem = (st.xem===id ? '' : id); ve(); };
  kd.chiaSe = function(id, bat){
    kd.goi('chiaSe',{id:id, congKhai:bat}).then(function(d){
      (st.phim||[]).forEach(function(p){ if(p.id===id) p.congKhai=bat; });
      U.toast(bat?'Đã bật chia sẻ: ai có link đều xem được.':'Đã tắt chia sẻ: chỉ chủ kho xem.','ok'); ve();
      if(bat && navigator.clipboard) navigator.clipboard.writeText(d.link).catch(function(){});
    }).catch(function(e){ U.toast(e.message,'err'); });
  };
  kd.chep = function(id){ var l=kd.link(id);
    if(navigator.clipboard) navigator.clipboard.writeText(l).then(function(){ U.toast('Đã chép link.','ok'); }, function(){ U.toast(l,'ok'); });
    else U.toast(l,'ok'); };
  kd.xoa = function(id, ten){
    if(!window.confirm('Bỏ phim "'+ten+'" vào Thùng rác Drive? (khôi phục được trong 30 ngày)')) return;
    kd.goi('xoa',{id:id}).then(function(){ st.phim=(st.phim||[]).filter(function(p){ return p.id!==id; }); U.toast('Đã bỏ vào Thùng rác.','ok'); ve(); })
      .catch(function(e){ U.toast(e.message,'err'); });
  };

  kd.ve = function(){
    var c = kd.cfg();
    var o = U.sec('Kho phim · Google Drive','Mọi phim GITA365 lưu trong Drive 2TB của anh/chị — xem, chia sẻ, tải về ở một chỗ');
    if(kd.coKho()){
      if(!st.phim && !st.dangTai && !st.loi) setTimeout(kd.tai, 0);
      var d = st.dung, pt = d && d.toiDa ? Math.min(100, d.daDung/d.toiDa*100) : 0;
      o += '<div class="card pad-sm mb"><div class="row" style="justify-content:space-between;align-items:baseline;gap:8px;flex-wrap:wrap">'+
          '<b class="sm">Dung lượng Drive</b><span class="tiny muted">'+(d? gb(d.daDung)+' / '+gb(d.toiDa)+' · còn '+gb(Math.max(0,d.toiDa-d.daDung)) : (st.dangTai?'đang đọc…':''))+'</span></div>'+
        '<div style="height:10px;border-radius:6px;background:var(--line);overflow:hidden;margin-top:8px"><div style="height:100%;width:'+pt.toFixed(1)+'%;background:'+(pt>90?'#B42318':(pt>75?'#B4720F':'#0B7350'))+'"></div></div>'+
        '<p class="bd-tip" style="margin-top:6px">Một phim 60 giây 1080p ≈ 40–80 MB → 2TB chứa được hàng chục nghìn phim. '+
          (d? (d.noiMay?'Máy dựng miễn phí: <b>đã nối</b>.':'Máy dựng miễn phí: <b>chưa nối</b> (GH_TOKEN) — phim vẫn lưu được, việc làm phim cần bấm tay trên GitHub.') : '')+'</p>'+
        '<div class="row mt" style="gap:8px"><button class="btn ghost sm" onclick="G.khoDrive.tai()">'+(st.dangTai?'Đang tải…':'↻ Làm mới')+'</button>'+
        '<a class="btn ghost sm" target="_blank" rel="noopener" href="'+(d&&/^[A-Za-z0-9_-]+$/.test(d.thuMuc||'')?'https://drive.google.com/drive/folders/'+d.thuMuc:'https://drive.google.com/drive/search?q=%22GITA365%20%C2%B7%20Kho%20phim%22')+'">Mở thư mục trên Drive</a></div></div>';
      if(st.loi) o += '<p class="bd-tip" style="color:#B42318">'+h(st.loi)+'</p>';
      if(st.phim){
        if(!st.phim.length) o += '<div class="card pad-sm mb"><p class="tiny muted">Kho chưa có phim. Phim làm xong ở tab "Làm phim nhanh" sẽ tự vào đây; phim có sẵn thì kéo vào thư mục <b>GITA365 · Kho phim/Phim</b> trên Drive.</p></div>';
        o += st.phim.map(function(p){
          var dang = st.xem===p.id;
          return '<div class="card pad-sm mb"><div class="row" style="justify-content:space-between;gap:8px;flex-wrap:wrap;align-items:center">'+
              '<div style="min-width:0;flex:1"><b class="sm" style="word-break:break-word">🎬 '+h(p.ten)+'</b>'+
                '<div class="tiny muted">'+h(new Date(p.ngay).toLocaleString('vi-VN'))+' · '+mb(p.kichThuoc)+(p.thuMuc?' · '+h(p.thuMuc):'')+' · '+
                (p.congKhai?'<span style="color:#0B7350">đang chia sẻ link</span>':'riêng tư')+'</div></div>'+
              '<div class="row" style="gap:6px;flex-wrap:wrap">'+
                '<button class="btn sm" onclick="G.khoDrive.moXem(\''+h(p.id)+'\')">'+(dang?'Đóng':'▶ Xem')+'</button>'+
                '<a class="btn ghost sm" target="_blank" rel="noopener" href="'+h(kd.link(p.id))+'">Mở Drive / Tải</a>'+
                (p.congKhai ? '<button class="btn ghost sm" onclick="G.khoDrive.chep(\''+h(p.id)+'\')">Chép link</button><button class="btn ghost sm" onclick="G.khoDrive.chiaSe(\''+h(p.id)+'\',false)">Tắt chia sẻ</button>'
                            : '<button class="btn ghost sm" onclick="G.khoDrive.chiaSe(\''+h(p.id)+'\',true)">Chia sẻ link</button>')+
                '<button class="btn ghost sm" onclick="G.khoDrive.xoa(\''+h(p.id)+'\',\''+h(p.ten.replace(/[\'"\\]/g,''))+'\')">Bỏ</button></div></div>'+
            (dang ? '<div style="position:relative;width:100%;max-width:520px;aspect-ratio:9/16;margin:10px auto 0;max-height:75vh">'+
                '<iframe src="'+h(kd.xem(p.id))+'" allow="autoplay; fullscreen" allowfullscreen style="position:absolute;inset:0;width:100%;height:100%;border:0;border-radius:12px;background:#000"></iframe></div>'+
                '<p class="tiny muted" style="text-align:center;margin-top:4px">Phim vừa tải lên cần vài phút để Drive xử lý trước khi xem được.</p>' : '')+
            '</div>';
        }).join('');
      }
    }
    o += '<details class="card pad-sm"'+(kd.coKho()?'':' open')+'><summary class="sm" style="cursor:pointer"><b>Cài đặt kho Drive</b> <span class="tiny muted">'+(kd.coKho()?'· đã nối':'· làm một lần')+'</span></summary>'+
      '<div class="grid g2 mt" style="gap:8px"><input id="kd-url" type="url" placeholder="https://script.google.com/macros/s/…/exec" value="'+h(c.url)+'" style="padding:8px;border:1px solid var(--line);border-radius:8px">'+
      '<input id="kd-khoa" type="password" placeholder="KHOA_APP" value="'+h(c.khoa)+'" style="padding:8px;border:1px solid var(--line);border-radius:8px"></div>'+
      '<div class="row mt"><button class="btn sm" onclick="G.khoDrive.luuCaiDat()">Lưu & kiểm tra</button></div>'+
      '<p class="bd-tip">Hướng dẫn 10 phút: <b>xuong-phim-ai/kho-drive/README-kho-drive.md</b> — dán mã vào Apps Script, chạy <b>caiDat</b>, triển khai Web app, dán địa chỉ + KHOA_APP vào đây.</p></details>';
    return o;
  };
})();

})();

/* ═════════ src/phim-nhanh.js ═════════ */
(function(){
/* ═══════════════════════════════════════════════════════════════
   GITA 365 · XƯỞNG PHIM — LÀM PHIM NHANH (3 bước, ~15 phút, 1080p)

   Chủ hệ chỉ làm 3 việc:  ① chọn ảnh mẫu nhân vật  ② dán kịch bản
   ③ bấm "Làm phim". Xưởng tự:
     · đọc kịch bản → phân cảnh, chọn phim trường, hành động, góc máy
       (bộ đọc luật tiếng Việt chạy ngay trong trình duyệt, không gửi đi đâu)
     · gửi lên trạm Cloudflare → máy GPU nội bộ chạy SONG SONG từng cảnh
       (model mở: Qwen-Image-Edit · Wan 2.2 · InfiniteTalk · VieNeu-TTS)
     · ráp 1080p, phụ đề, thẻ tên, nhạc → trả video về đây để xem/tải.
   Trình duyệt chỉ giữ địa chỉ trạm + mật khẩu gửi (localStorage), không
   giữ khoá máy GPU. Dữ liệu màn này lưu qua phiên: G.S.axN. View con của
   san-xuat-ai (tab "Làm phim nhanh"); mở cho qt_trang.
   ═══════════════════════════════════════════════════════════════ */
'use strict';
var G = window.G || {}; window.G = G;
(function(){
  var U = G.U, h = U.h, ic = U.ic;
  var axn = G.axn = G.axn || {};
  var TOI_DA_CANH = 14;                       /* giữ mốc ~15 phút: mỗi cảnh một máy GPU chạy song song */

  /* ── Phim trường nội bộ: từ khoá tiếng Việt → mô tả tiếng Anh cho mô hình ── */
  var BOI_CANH = [
    ['bc-sanh', /sảnh|lobby/, 'a luxurious modern lobby of the GITA365 ecosystem, large LED wall, polished marble floor, green plants, navy blue and gold interior'],
    ['bc-bucgiang', /bục giảng|giảng đường|studio|trường quay/, 'a professional training studio stage with a large screen behind, warm wood paneling, soft key light'],
    ['bc-hoithao', /hội thảo|hội trường|hội nghị/, 'a bright conference hall with neat rows of chairs, glass windows, green plants, natural light'],
    ['bc-lophoc', /lớp học|lớp|phòng học/, 'a modern training classroom with a whiteboard, green plants, natural daylight'],
    ['bc-vanphong', /văn phòng|phòng làm việc|công ty/, 'an upscale executive office with wooden bookshelves, glass windows overlooking the city, warm lights'],
    ['bc-sankhau', /sân khấu|sự kiện|lễ/, 'an event stage with a navy blue and gold backdrop, stage lighting, audience silhouettes'],
    ['bc-coach', /coach|1-1|tư vấn riêng/, 'a cozy one-on-one coaching room with a sofa, green plants, soft warm light'],
    ['bc-phongkhach', /phòng khách|trong nhà|ở nhà|gia đình/, 'an elegant family living room with a sofa, bookshelves, plants, warm afternoon sunlight'],
    ['bc-vuontre', /vườn|tre|công viên|ngoài trời/, 'a green bamboo garden path with a traditional wooden house in the distance, sunlight through the leaves'],
    ['bc-bep', /bếp|nấu/, 'a modern family kitchen with a kitchen island, fresh vegetables, large glass window'],
    ['bc-bien', /biển|bãi cát/, 'a sunny beach with gentle waves, golden sand, clear blue sky']
  ];
  /* ── Hành động: từ khoá → mã (động cơ có sẵn ngữ pháp chuyển động tiếng Anh cho từng mã) ── */
  var HANH = [
    ['chay', /\bchạy\b/], ['bat_tay', /bắt tay/], ['om', /\bôm\b/], ['dua_do', /trao|đưa cho|tặng/],
    ['cam_do', /cầm|nhấc|giơ/], ['ngoi_xuong', /ngồi xuống|ngồi/], ['dung_len', /đứng dậy|đứng lên/],
    ['rot_tra', /rót/], ['go_may', /gõ máy|máy tính|laptop/], ['vay_tay', /vẫy tay|chào/],
    ['thuyet_trinh', /thuyết trình|giảng|chỉ (lên |vào )?màn hình/], ['tro_chuyen', /trò chuyện|nói chuyện/],
    ['di_bo', /đi bộ|bước|đi dạo|tiến vào|đi vào|\bđi\b/], ['gat_dau', /gật đầu|lắng nghe/]
  ];
  var MAU = '[Bục giảng studio GITA]\n' +
    'Trainer: Chào anh chị, hôm nay chúng ta cùng nói về kỷ luật tài chính của gia đình.\n' +
    'MC: Thưa thầy, một gia đình trẻ nên bắt đầu từ đâu ạ?\n' +
    'Trainer: Bắt đầu từ một thói quen nhỏ: ghi lại mọi khoản chi trong ba mươi ngày.\n\n' +
    '[Vườn tre] Trainer đi bộ chậm, mỉm cười nhìn về phía máy.\n' +
    'Trainer: Kỷ luật hôm nay là tự do của ngày mai. Hẹn gặp anh chị ở GITA365.';

  function boDau(s){ return (s||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/đ/g,'d').trim(); }
  function lsGet(k){ try{ return window.localStorage.getItem(k)||''; }catch(e){ return ''; } }
  function lsSet(k,v){ try{ window.localStorage.setItem(k,v); }catch(e){} }
  function tram(){ return { worker:lsGet('axWorker').replace(/\/+$/,''), token:lsGet('axToken') }; }
  function luu(){ if(G.save) G.save(); }
  /* Đường làm phim: đã nối kho Google Drive → MIỄN PHÍ (Drive + GitHub + Kaggle, vài giờ);
     không thì trạm Cloudflare + máy GPU thuê (~15 phút). */
  function kd(){ return G.khoDrive && G.khoDrive.coKho() ? G.khoDrive : null; }
  function anhCua(n){ return kd() ? n.anhDrive : n.anh; }

  function st(){
    if(!G.S.axN){
      var goc = (G.S.axNV||[]).filter(function(n){ return n.vai==='trainer'||n.vai==='mc'; }).slice(0,2);
      if(!goc.length) goc=[{id:'nv-trainer',ten:'Trainer Trương Nhật Quang',vai:'trainer',gioi:'nam',tuoi:'lon'},{id:'nv-mc',ten:'MC GITA',vai:'mc',gioi:'nu',tuoi:'lon'}];
      G.S.axN = { nv: goc.map(function(n){ return {id:n.id, ten:n.ten, vai:n.vai, gioi:n.gioi||'nam', tuoi:n.tuoi||'lon', anh:'', thumb:''}; }),
        kichBan: MAU, khung:'doc', ngonNgu:'vi', job:'', lichSu:[] };
    }
    return G.S.axN;
  }

  /* ════════ BỘ ĐỌC KỊCH BẢN → KẾ HOẠCH CẢNH (chạy trong trình duyệt) ════════ */
  function timNguoi(nhan, ds){
    var k = boDau(nhan);
    var vai = /trainer|thay|giang vien|chuyen gia/.test(k) ? 'trainer' : (/\bmc\b|dan chuong trinh|nguoi dan/.test(k) ? 'mc' : '');
    for(var i=0;i<ds.length;i++){
      var t = boDau(ds[i].ten);
      if(t===k || t.indexOf(k)>=0 || k.indexOf(t)>=0) return ds[i];
      var tu = t.split(/\s+/).filter(function(x){ return x.length>2; });
      if(tu.some(function(x){ return new RegExp('\\b'+x+'\\b').test(k); }) && !/^(trainer|mc|gita)$/.test(k)) return ds[i];
    }
    if(vai) for(var j=0;j<ds.length;j++) if(ds[j].vai===vai) return ds[j];
    return null;
  }
  function nguoiTrongMoTa(moTa, ds){ var k=boDau(moTa); return ds.filter(function(n){
      var t=boDau(n.ten).split(/\s+/).filter(function(x){return x.length>2 && !/^(gita|gita365|trainer)$/.test(x);});
      return t.some(function(x){ return k.indexOf(x)>=0; }) || (n.vai==='trainer'&&/trainer|thay/.test(k)) || (n.vai==='mc'&&/\bmc\b/.test(k)); }); }
  function catCau(text, toiDa){
    var cau = text.match(/[^.!?…]+[.!?…]*/g) || [text], ra=[], cur='';
    cau.forEach(function(c){ c=c.trim(); if(!c) return;
      var n=(cur+' '+c).trim().split(/\s+/).length;
      if(cur && n>toiDa){ ra.push(cur); cur=c; } else cur=(cur+' '+c).trim(); });
    if(cur) ra.push(cur); return ra;
  }
  function giayNoi(t){ return Math.max(3, Math.min(14, Math.round((t.split(/\s+/).length/3.0 + 0.8)*10)/10)); }

  axn.st = st;                                   /* tab Dự án phim dùng chung dàn nhân vật + ảnh mẫu */
  axn.nguoiTrong = nguoiTrongMoTa;              /* dùng chung cho tab Dự án phim */
  axn.BOI_CANH = BOI_CANH;
  axn.doc = function(kichBan, ds, toiDaTu){
    var canh=[], canhBao=[], bc=null, bcTruoc=null;
    var khoi = (kichBan||'').replace(/\r/g,'').split(/\n\s*\n/);
    khoi.forEach(function(k){
      var moTa=[], thoai=[], noi=[];
      k.split('\n').forEach(function(d){ d=d.trim(); if(!d) return;
        var m = d.match(/^[\[(]([^\])]+)[\])]\s*(.*)$/);
        if(m){ noi.push(m[1]); if(m[2]) moTa.push(m[2]); return; }
        var t = d.match(/^([^:：]{1,32})[:：]\s*(.+)$/);
        if(t){ var ng=timNguoi(t[1], ds);
          if(!ng){ canhBao.push('Không nhận ra người nói "'+t[1].trim()+'" — tạm giao cho '+((ds[0]||{}).ten||'nhân vật 1')+'.'); ng=ds[0]; }
          if(ng) thoai.push({nv:ng.id, text:t[2].trim()}); return; }
        moTa.push(d); });
      var mt = moTa.join('. '), chon = noi.join('. ');            /* [..] = nơi quay · câu thường = hành động */
      var tim = BOI_CANH.filter(function(b){ return b[1].test((chon||mt).toLowerCase()); })[0];
      if(tim) bc=tim; if(!bc) bc=BOI_CANH[1];
      var hd = (HANH.filter(function(x){ return x[1].test(mt.toLowerCase()); })[0]||[''])[0];
      var co = nguoiTrongMoTa(mt, ds);
      if((mt||chon) && (!thoai.length || bc!==bcTruoc)){        /* cảnh diễn / cảnh mở bối cảnh mới */
        var dong = hd==='di_bo'||hd==='chay'||hd==='di_ngang';
        var nvs = (co.length?co:[ds.filter(function(n){ return thoai.length && n.id===thoai[0].nv; })[0]||ds[0]]).filter(Boolean).slice(0,2);
        canh.push({ loai:'dien', nv:nvs.map(function(n){return n.id;}), mo_ta:mt||chon, hanh_dong:hd, bc_id:bc[0], boi_canh_en:bc[2],
          giay: dong?6:(thoai.length?4:5),
          may: dong ? {co:'trung_rong',goc:'ngang_mat',chuyen:'bam_theo'} : (hd==='bat_tay'||hd==='om' ? {co:'trung',goc:'ngang_mat',chuyen:'xoay_quanh'} : (hd ? {co:'trung',goc:'ngang_mat',chuyen:'day_vao',cuong:0.3} : {co:'toan',goc:'ngang_mat',chuyen:'day_vao',cuong:0.35})) });
      }
      bcTruoc=bc;
      thoai.forEach(function(t){
        catCau(t.text, toiDaTu || 34).forEach(function(doan){
          var i = canh.filter(function(c){ return c.loai==='noi'; }).length;
          canh.push({ loai:'noi', nv:[t.nv], thoai:doan, mo_ta:mt, hanh_dong: hd==='thuyet_trinh'?'thuyet_trinh':'', bc_id:bc[0], boi_canh_en:bc[2],
            giay: giayNoi(doan), may: i%2 ? {co:'can',goc:'ngang_mat',chuyen:'tinh'} : {co:'trung',goc:'ngang_mat',chuyen:'day_vao',cuong:0.3} });
        });
      });
    });
    if(canh.length){ var cuoi=canh[canh.length-1]; if(cuoi.loai==='noi' && cuoi.may.chuyen==='tinh') cuoi.may={co:cuoi.may.co,goc:'ngang_mat',chuyen:'keo_ra',cuong:0.35}; }
    if(canh.length>TOI_DA_CANH) canhBao.push('Kịch bản ra '+canh.length+' cảnh — vượt '+TOI_DA_CANH+' cảnh thì quá mốc 15 phút. Nên tách thành 2 tập.');
    canh.forEach(function(c,i){ c.id='s'+(i+1); c.thu_tu=i+1; });
    return { canh:canh, canhBao:canhBao, tongGiay: Math.round(canh.reduce(function(s,c){ return s+c.giay; },0)) };
  };

  /* ════════ ẢNH MẪU: thu nhỏ trên máy rồi gửi lên trạm ════════ */
  function thuNho(file, canh, chat){
    return new Promise(function(ok, loi){
      var r = new FileReader();
      r.onerror = function(){ loi(new Error('Không đọc được ảnh')); };
      r.onload = function(){ var im = new Image();
        im.onerror = function(){ loi(new Error('Tệp không phải ảnh')); };
        im.onload = function(){ var s = Math.min(1, canh/Math.max(im.width, im.height));
          var cv = document.createElement('canvas'); cv.width = Math.round(im.width*s); cv.height = Math.round(im.height*s);
          cv.getContext('2d').drawImage(im, 0, 0, cv.width, cv.height); ok(cv.toDataURL('image/jpeg', chat)); };
        im.src = r.result; };
      r.readAsDataURL(file);
    });
  }
  axn.chonAnh = function(i, input){
    var f = input.files && input.files[0]; if(!f) return;
    var s = st(), n = s.nv[i], t = tram(), k = kd();
    if(!k && !t.worker){ return U.toast('Chưa nối kho Drive hay trạm — mở tab "Kho phim" để nối Google Drive.','err'); }
    Promise.all([thuNho(f, 1280, 0.9), thuNho(f, 160, 0.8)]).then(function(kq){
      n.thumb = kq[1]; ve();
      if(k) return k.goi('taiAnh', { id:n.id, data:kq[0] });
      return fetch(t.worker+'/api/anh', { method:'POST', headers:{'content-type':'application/json','x-gita-token':t.token},
        body: JSON.stringify({ id:n.id, data:kq[0] }) }).then(function(r){ return r.json(); });
    }).then(function(d){
      if(d && k && d.id){ n.anhDrive = d.id; luu(); ve(); U.toast('Đã lưu ảnh '+n.ten+' vào Drive','ok'); }
      else if(d && d.key){ n.anh = d.key; luu(); ve(); U.toast('Đã gửi ảnh '+n.ten,'ok'); }
      else U.toast((d&&d.loi)||'Gửi ảnh thất bại','err');
    }).catch(function(e){ U.toast('Lỗi ảnh: '+(e&&e.message),'err'); });
  };
  axn.nvSua = function(i, k, v){ var n=st().nv[i]; if(!n) return; n[k]=v; luu(); };
  axn.nvThem = function(){ var s=st(); if(s.nv.length>=4) return U.toast('Tối đa 4 nhân vật cho một video nhanh.','err');
    s.nv.push({ id:'nv-'+Math.random().toString(36).slice(2,7), ten:'Nhân vật '+(s.nv.length+1), vai:'dienvien', gioi:'nam', tuoi:'lon', anh:'', thumb:'' }); luu(); ve(); };
  axn.nvXoa = function(i){ var s=st(); if(s.nv.length<=1) return; s.nv.splice(i,1); luu(); ve(); };
  axn.kichBan = function(v){ st().kichBan=v; luu(); var el=document.getElementById('axn-doc'); if(el) el.innerHTML=veDoc(); };
  axn.dat = function(k,v){ st()[k]=v; luu(); ve(); };
  axn.mau = function(){ st().kichBan=MAU; luu(); ve(); };

  /* ════════ GỬI LÀM PHIM + THEO DÕI ════════ */
  function giongKey(n){ return (n.gioi||'nam')+'-'+(n.tuoi||'lon'); }
  axn.lamPhim = function(){
    var s=st(), t=tram(), k=kd();
    if(!k && (!t.worker || !t.token)) return U.toast('Chưa nối kho Drive — mở tab "Kho phim" để nối Google Drive.','err');
    var kh = axn.doc(s.kichBan, s.nv);
    if(!kh.canh.length) return U.toast('Kịch bản chưa có cảnh nào.','err');
    var dung = {}; kh.canh.forEach(function(c){ c.nv.forEach(function(id){ dung[id]=1; }); });
    var thieu = s.nv.filter(function(n){ return dung[n.id] && !anhCua(n); });
    if(thieu.length) return U.toast('Còn thiếu ảnh mẫu: '+thieu.map(function(n){return n.ten;}).join(', '),'err');
    var goi = { tieu_de: (s.kichBan.split('\n').filter(function(x){return x.trim();})[0]||'Phim GITA').slice(0,80),
      khung: s.khung, ngon_ngu: s.ngonNgu, kich_ban: s.kichBan,
      nhan_vat: s.nv.filter(function(n){ return dung[n.id]; }).map(function(n){ return {id:n.id, ten:n.ten, vai:n.vai, gioi:n.gioi, tuoi:n.tuoi, giong_key:giongKey(n), anh:anhCua(n)}; }),
      canh: kh.canh };
    s.job=''; s.duong = k ? 'drive' : 'tram';
    s.tt={trangThai:'queued', buoc: k ? 'Đang gửi việc vào kho Drive…' : 'Đang gửi lên trạm…', phanTram:1}; s.batDau=Date.now(); luu(); ve();
    var nhan = function(d){
        if(!d.jobid){ s.tt={trangThai:'error', buoc:d.loi||'Gửi thất bại'}; luu(); ve(); return; }
        s.job=d.jobid; s.lichSu.unshift({job:d.jobid, ten:goi.tieu_de, luc:new Date().toISOString(), canh:kh.canh.length, duong:s.duong});
        s.lichSu=s.lichSu.slice(0,10); luu(); axn.theoDoi(); };
    if(k){ k.goi('datViec', { ke_hoach:goi }).then(nhan).catch(function(e){ s.tt={trangThai:'error', buoc:e.message}; luu(); ve(); }); return; }
    fetch(t.worker+'/api/nhanh', { method:'POST', headers:{'content-type':'application/json','x-gita-token':t.token}, body:JSON.stringify(goi) })
      .then(function(r){ return r.json(); })
      .then(nhan)
      .catch(function(e){ s.tt={trangThai:'error', buoc:'Không gọi được trạm: '+(e&&e.message)}; luu(); ve(); });
  };
  axn.theoDoi = function(){
    var s=st(), t=tram(); clearTimeout(axn._t);
    if(!s.job) return;
    var hoi = s.duong==='drive' ? (kd() ? kd().goi('trangThai', {jobid:s.job}) : null)
                                : (t.worker ? fetch(t.worker+'/api/phim/'+s.job).then(function(r){ return r.json(); }) : null);
    if(!hoi) return;
    hoi.then(function(d){
      s.tt=d; luu(); veTienDo();
      if(d.trangThai!=='done' && d.trangThai!=='error') axn._t=setTimeout(axn.theoDoi, s.duong==='drive' ? 30000 : 6000);
      else ve();
    }).catch(function(){ axn._t=setTimeout(axn.theoDoi, 10000); });
  };
  axn.luuTram = function(){
    var w=(document.getElementById('axn-w')||{}).value||'', k=(document.getElementById('axn-k')||{}).value||'';
    if(!/^https:\/\//.test(w.trim())) return U.toast('Địa chỉ trạm phải bắt đầu bằng https://','err');
    lsSet('axWorker', w.trim()); lsSet('axToken', k.trim()); U.toast('Đã lưu cài đặt trạm trên máy này.','ok'); ve();
  };

  /* ════════ GIAO DIỆN ════════ */
  function ve(){ if(G.render) G.render(); }
  function mmss(ms){ var s=Math.max(0,Math.round(ms/1000)); return Math.floor(s/60)+':'+('0'+(s%60)).slice(-2); }
  function veDoc(){
    var s=st(), kh=axn.doc(s.kichBan, s.nv);
    var dem = {noi:0, dien:0}; kh.canh.forEach(function(c){ dem[c.loai]++; });
    return '<div class="row" style="gap:8px;flex-wrap:wrap;align-items:center">'+
        '<span class="bd-chip">'+kh.canh.length+' cảnh</span><span class="bd-chip">'+dem.noi+' cảnh nói</span><span class="bd-chip">'+dem.dien+' cảnh diễn</span>'+
        '<span class="bd-chip">~'+kh.tongGiay+' giây phim</span></div>'+
      (kh.canhBao.length ? '<p class="bd-tip" style="color:#B4720F;margin-top:6px">'+kh.canhBao.map(h).join('<br>')+'</p>' : '')+
      '<details style="margin-top:8px"><summary class="tiny muted" style="cursor:pointer">Xem xưởng phân cảnh thế nào</summary>'+
      '<ol class="tiny" style="margin:6px 0 0 18px;color:var(--ink-2);line-height:1.6">'+kh.canh.map(function(c){
        var ten = c.nv.map(function(id){ return (s.nv.filter(function(n){return n.id===id;})[0]||{}).ten||id; }).join(' + ');
        return '<li><b>'+(c.loai==='noi'?'Nói':'Diễn')+'</b> · '+h(ten)+' · '+c.giay+'s · 🎥 '+h(c.may.co+' / '+c.may.chuyen)+
          (c.thoai?' — “'+h(c.thoai.slice(0,70))+(c.thoai.length>70?'…':'')+'”':(c.mo_ta?' — '+h(c.mo_ta.slice(0,60)):''))+'</li>'; }).join('')+'</ol></details>';
  }
  function veTienDo(){
    var el=document.getElementById('axn-td'); if(el) el.innerHTML=htmlTienDo();
  }
  function htmlTienDo(){
    var s=st(), d=s.tt; if(!d) return '';
    var pt = d.trangThai==='done'?100:Math.max(2, Math.min(99, +d.phanTram||0));
    var mau = d.trangThai==='error' ? '#B42318' : (d.trangThai==='done' ? '#0B7350' : 'var(--gita)');
    var o = '<div class="row" style="justify-content:space-between;align-items:baseline;gap:8px;flex-wrap:wrap">'+
      '<b class="sm">'+(d.trangThai==='done'?'✅ Phim xong':(d.trangThai==='error'?'⚠ Dừng lại':'⏳ Xưởng đang làm'))+'</b>'+
      '<span class="tiny muted">'+(s.batDau?'đã chạy '+mmss((d.xong?Date.parse(d.xong):Date.now())-s.batDau)+(s.duong==='drive'?' · đường miễn phí, thường vài giờ':' · mốc 15:00'):'')+'</span></div>'+
      '<div style="height:10px;border-radius:6px;background:var(--line);overflow:hidden;margin-top:8px"><div style="height:100%;width:'+pt+'%;background:'+mau+';transition:width .6s"></div></div>'+
      '<p class="tiny" style="margin-top:6px;color:var(--ink-2)">'+h(d.buoc||'')+'</p>';
    if(d.trangThai==='done' && s.duong==='drive' && d.phimId && G.khoDrive){
      o += '<div style="position:relative;width:100%;max-width:480px;aspect-ratio:'+(s.khung==='ngang'?'16/9':'9/16')+';margin:10px auto 0;max-height:75vh">'+
          '<iframe src="'+h(G.khoDrive.xem(d.phimId))+'" allow="autoplay; fullscreen" allowfullscreen style="position:absolute;inset:0;width:100%;height:100%;border:0;border-radius:12px;background:#000"></iframe></div>'+
        '<div class="row mt" style="gap:8px;flex-wrap:wrap">'+
          '<a class="btn" target="_blank" rel="noopener" href="'+h(G.khoDrive.link(d.phimId))+'">⬇ Mở / tải trên Drive</a>'+
          (d.phimPhuDeId?'<a class="btn ghost" target="_blank" rel="noopener" href="'+h(G.khoDrive.link(d.phimPhuDeId))+'">Bản có phụ đề</a>':'')+
          '<button class="btn ghost" onclick="G.ax.tab(\'khophim\')">Xem trong Kho phim</button></div>';
    } else if(d.trangThai==='done' && s.job){
      var w=tram().worker;
      o += '<video controls playsinline style="width:100%;max-height:70vh;border-radius:12px;margin-top:10px;background:#000" src="'+h(w+'/api/phim/'+s.job+'/video')+'"></video>'+
        '<div class="row mt" style="gap:8px;flex-wrap:wrap">'+
          '<a class="btn" href="'+h(w+'/api/phim/'+s.job+'/video?tai=1')+'">⬇ Tải video 1080p</a>'+
          '<a class="btn ghost" href="'+h(w+'/api/phim/'+s.job+'/video?ban=phude&tai=1')+'">Tải bản có phụ đề</a></div>';
    }
    return o;
  }
  axn.ve = function(){
    var s=st(), t=tram();
    var o = U.sec('Làm phim nhanh','Gửi ảnh mẫu + kịch bản → xưởng tự làm từ A đến Z → video 1080p lưu vào Google Drive');
    /* Bước 1 · ảnh mẫu */
    o += '<div class="card pad-sm mb"><b class="sm">① Ảnh mẫu nhân vật</b><p class="tiny muted" style="margin:4px 0 8px">Ảnh rõ mặt, nhìn thẳng, đủ sáng. Mỗi người một ảnh là đủ.</p>'+
      '<div class="grid g2" style="gap:10px">'+s.nv.map(function(n,i){
        return '<div style="display:flex;gap:10px;align-items:center;border:1px solid var(--line);border-radius:12px;padding:8px">'+
          '<label style="width:64px;height:64px;border-radius:10px;flex:none;cursor:pointer;background:var(--line) center/cover no-repeat'+(n.thumb?' url('+n.thumb+')':'')+';display:flex;align-items:center;justify-content:center;font-size:22px" title="Chọn ảnh">'+
            (n.thumb?'':'📷')+'<input type="file" accept="image/*" style="display:none" onchange="G.axn.chonAnh('+i+',this)"></label>'+
          '<div style="flex:1;min-width:0;display:flex;flex-direction:column;gap:4px">'+
            '<input type="text" value="'+h(n.ten)+'" onchange="G.axn.nvSua('+i+',\'ten\',this.value)" style="padding:6px;border:1px solid var(--line);border-radius:8px">'+
            '<div class="row" style="gap:4px;flex-wrap:wrap">'+
              '<select onchange="G.axn.nvSua('+i+',\'gioi\',this.value)" style="padding:4px;border:1px solid var(--line);border-radius:8px"><option value="nam"'+(n.gioi==='nam'?' selected':'')+'>Nam</option><option value="nu"'+(n.gioi==='nu'?' selected':'')+'>Nữ</option></select>'+
              '<select onchange="G.axn.nvSua('+i+',\'tuoi\',this.value)" style="padding:4px;border:1px solid var(--line);border-radius:8px"><option value="lon"'+(n.tuoi==='lon'?' selected':'')+'>Người lớn</option><option value="teen"'+(n.tuoi==='teen'?' selected':'')+'>Thiếu niên</option><option value="treem"'+(n.tuoi==='treem'?' selected':'')+'>Trẻ em</option></select>'+
              '<span class="tiny" style="color:'+(anhCua(n)?'#0B7350':'#B4720F')+'">'+(anhCua(n)?'✓ đã gửi ảnh':'chưa có ảnh')+'</span>'+
              (s.nv.length>1?'<button class="btn ghost sm" style="padding:2px 8px" onclick="G.axn.nvXoa('+i+')">Bỏ</button>':'')+'</div></div></div>';
      }).join('')+'</div>'+
      (s.nv.length<4?'<button class="btn ghost sm mt" onclick="G.axn.nvThem()">+ Thêm nhân vật</button>':'')+'</div>';
    /* Bước 2 · kịch bản */
    o += '<div class="card pad-sm mb"><b class="sm">② Kịch bản</b>'+
      '<p class="tiny muted" style="margin:4px 0 8px">Mỗi đoạn cách nhau một dòng trống. <b>[Bối cảnh]</b> ở đầu đoạn · <b>Tên: lời thoại</b> cho người nói · câu thường là hành động.</p>'+
      '<textarea rows="9" oninput="G.axn.kichBan(this.value)" style="width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--line);border-radius:10px;font-size:14px;line-height:1.5">'+h(s.kichBan)+'</textarea>'+
      '<div class="row mt" style="gap:8px;flex-wrap:wrap;align-items:center">'+
        '<select onchange="G.axn.dat(\'khung\',this.value)" style="padding:6px;border:1px solid var(--line);border-radius:8px"><option value="doc"'+(s.khung==='doc'?' selected':'')+'>Dọc 9:16 · Reels/TikTok</option><option value="ngang"'+(s.khung==='ngang'?' selected':'')+'>Ngang 16:9 · YouTube</option></select>'+
        '<select onchange="G.axn.dat(\'ngonNgu\',this.value)" style="padding:6px;border:1px solid var(--line);border-radius:8px"><option value="vi"'+(s.ngonNgu==='vi'?' selected':'')+'>Tiếng Việt</option><option value="en"'+(s.ngonNgu==='en'?' selected':'')+'>English</option></select>'+
        '<button class="btn ghost sm" onclick="G.axn.mau()">Dùng kịch bản mẫu</button></div>'+
      '<div id="axn-doc" style="margin-top:10px">'+veDoc()+'</div></div>';
    /* Bước 3 · làm phim */
    var dangChay = s.tt && s.job && s.tt.trangThai!=='done' && s.tt.trangThai!=='error';
    o += '<div class="card pad-sm mb"><b class="sm">③ Làm phim</b><div class="row mt" style="gap:8px;flex-wrap:wrap;align-items:center">'+
      '<button class="btn" '+(dangChay?'disabled':'')+' onclick="G.axn.lamPhim()">'+ic('spark','w-3 h-3')+(dangChay?'Đang làm…':'🎬 Làm phim')+'</button>'+
      '<span class="tiny muted">Video 1080p · giọng chuẩn phát sóng · phụ đề · thẻ tên · nhạc nền · '+(kd()?'<b>đường miễn phí</b>: lưu thẳng vào Google Drive (Kaggle GPU, thường vài giờ)':(t.worker?'máy GPU thuê, ~15 phút':'<b>chưa nối</b> — mở tab Kho phim để nối Google Drive'))+'</span></div>'+
      '<div id="axn-td" style="margin-top:10px">'+htmlTienDo()+'</div></div>';
    if(s.lichSu.length>1) o += '<div class="card pad-sm mb"><b class="sm">Phim đã làm</b><ul class="tiny" style="margin:6px 0 0 18px;line-height:1.7">'+
      s.lichSu.map(function(x){ return '<li>'+(x.duong==='drive' ? h(x.ten)+' · <a href="javascript:void 0" onclick="G.ax.tab(\'khophim\')">trong Kho phim</a>' : '<a href="'+h(t.worker+'/api/phim/'+x.job+'/video?tai=1')+'">'+h(x.ten)+'</a>')+' · '+x.canh+' cảnh · '+h(new Date(x.luc).toLocaleString('vi-VN'))+'</li>'; }).join('')+'</ul></div>';
    /* Cài đặt một lần */
    o += '<details class="card pad-sm"><summary class="sm" style="cursor:pointer"><b>Máy GPU thuê (tuỳ chọn, ~15 phút)</b> <span class="tiny muted">'+(t.worker?'· đã nối trạm':'· chưa dùng — mặc định đi đường miễn phí qua Google Drive')+'</span></summary>'+
      '<div class="grid g2 mt" style="gap:8px"><input id="axn-w" type="url" placeholder="https://gita-xuong-phim….workers.dev" value="'+h(t.worker)+'" style="padding:8px;border:1px solid var(--line);border-radius:8px">'+
      '<input id="axn-k" type="password" placeholder="Mật khẩu gửi phim" value="'+h(t.token)+'" style="padding:8px;border:1px solid var(--line);border-radius:8px"></div>'+
      '<div class="row mt"><button class="btn sm" onclick="G.axn.luuTram()">Lưu</button></div>'+
      '<p class="bd-tip">Chỉ dùng khi thuê máy GPU (Modal). Đã nối kho Google Drive thì xưởng ưu tiên đường miễn phí. Hướng dẫn: <b>xuong-phim-ai/nhanh/README-nhanh.md</b>.</p></details>';
    if(dangChay) setTimeout(axn.theoDoi, 0);
    return o;
  };
})();

})();

/* ═════════ src/du-an-phim.js ═════════ */
(function(){
/* ═══════════════════════════════════════════════════════════════
   GITA 365 · XƯỞNG PHIM — DỰ ÁN PHIM (video 4–8 phút cao cấp, MIỄN PHÍ, nhiều lần/tháng)

   Cách tối ưu khi không thuê dịch vụ: AI chỉ làm phần KHÔNG quay được.
     · "quay"  — Trainer/MC nói, cảnh nhiều người chạm nhau → QUAY THẬT bằng điện thoại
                 (đúng mặt, đúng giọng, khớp môi tuyệt đối, không hình mờ, 0đ)
     · "stock" — cảnh nền không có nhân vật → video miễn phí Pexels/Pixabay
     · "ai"    — một nhân vật hành động mà không quay được → Kaggle GPU miễn phí
   App tự phân loại từng cảnh (sửa được), in danh sách quay, gợi ý từ khoá video nền,
   tạo thư mục dự án trên Google Drive, gửi dựng cảnh AI, rồi "Ráp phim": máy GitHub
   tải tệp từ Drive → giọng chuẩn phát sóng, màu, phụ đề, thẻ tên, nhạc → phim về Drive.
   Dùng chung bộ đọc kịch bản (G.axn) và kho Drive (G.khoDrive). Lưu: G.S.axDA.
   ═══════════════════════════════════════════════════════════════ */
'use strict';
var G = window.G || {}; window.G = G;
(function(){
  var U = G.U, h = U.h;
  var da = G.axda = G.axda || {};
  var NHOM = { quay:['🎥 Quay thật','#0B7350'], stock:['🎞 Video nền miễn phí','#2E5AAC'], ai:['✨ AI (Kaggle)','#7A3FB0'] };
  var THU_MUC = { quay:'Quay-that', stock:'Stock', ai:'AI' };
  var TU_KHOA = { 'bc-sanh':'modern office lobby', 'bc-bucgiang':'conference stage screen', 'bc-hoithao':'conference hall',
    'bc-lophoc':'modern classroom', 'bc-vanphong':'executive office city view', 'bc-sankhau':'event stage lights',
    'bc-coach':'cozy office sofa', 'bc-phongkhach':'family living room', 'bc-vuontre':'bamboo forest path',
    'bc-bep':'modern kitchen', 'bc-bien':'beach waves sunset' };
  /* từ khoá tiếng Việt trong mô tả → từ khoá tìm video nền (tiếng Anh) */
  var TU_DIEN = [[/thành phố|đô thị/,'city skyline'],[/bình minh/,'sunrise'],[/hoàng hôn/,'sunset'],[/biển/,'ocean waves'],
    [/núi/,'mountains'],[/đường phố|phố/,'street traffic'],[/cà phê|quán/,'coffee shop'],[/mưa/,'rain'],[/rừng/,'forest'],
    [/cánh đồng|lúa/,'rice field'],[/sông|hồ/,'river'],[/văn phòng/,'office'],[/bầu trời|mây/,'sky clouds'],[/đêm/,'night'],
    [/tiền|tài chính/,'money finance'],[/học|sách/,'books study'],[/gia đình/,'family home'],[/việt nam/,'vietnam']];
  function tuKhoa(c){
    var t=(c.mo_ta||'').toLowerCase(), k=TU_DIEN.filter(function(x){ return x[0].test(t); }).map(function(x){ return x[1]; });
    return k.length ? k.slice(0,3).join(' ') : (TU_KHOA[c.bc_id] || 'city skyline');
  }
  function bam(t){ var x=5381; for(var i=0;i<t.length;i++) x=((x<<5)+x+t.charCodeAt(i))|0; return (x>>>0).toString(36); }
  var CO = { dac_ta:'đặc tả', can:'cận', trung:'trung', trung_rong:'trung rộng', toan:'toàn' };
  var MAU = '[Bục giảng studio GITA]\n' +
    'Trainer: Chào anh chị, hôm nay chúng ta nói về kỷ luật tài chính của gia đình trẻ.\n' +
    'MC: Thưa thầy, vì sao nhiều gia đình thu nhập khá mà vẫn thiếu trước hụt sau?\n' +
    'Trainer: Vì tiền đi trước kế hoạch. Muốn đổi, hãy bắt đầu từ một thói quen nhỏ.\n\n' +
    '[Toàn cảnh thành phố lúc bình minh]\n\n' +
    '[Phòng khách] Người mẹ ngồi xuống bàn, mở sổ ghi chép chi tiêu.\n\n' +
    '[Văn phòng] Trainer và MC bắt tay, cùng cười.\n' +
    'Trainer: Kỷ luật hôm nay là tự do của ngày mai. Hẹn gặp anh chị ở tập sau.';

  function st(){
    if(!G.S.axDA) G.S.axDA = { ten:'Dự án phim GITA', kichBan:MAU, khung:'doc', chongRung:false, nhom:{}, duAn:'', link:'', tep:null, jobAI:'', ttAI:null, jobRap:'', ttRap:null };
    if(!G.S.axDA.cheDo) G.S.axDA.cheDo = 'ai100';     /* mặc định: 100% AI từ ảnh chủ hệ cung cấp */
    return G.S.axDA;
  }
  function cast(){ return (G.axn && G.axn.st ? G.axn.st().nv : (G.S.axN && G.S.axN.nv)) || []; }
  function luu(){ if(G.save) G.save(); }
  function ve(){ if(G.render) G.render(); }
  function kd(){ return G.khoDrive && G.khoDrive.coKho() ? G.khoDrive : null; }

  /* ── phân cảnh + phân loại ── */
  function tuDong(c, ds){
    if(c.loai==='noi') return 'quay';
    if(c.nv.length>1 || /^(bat_tay|om|dua_do|tro_chuyen)$/.test(c.hanh_dong||'')) return 'quay';
    if(!c.hanh_dong && !(G.axn.nguoiTrong(c.mo_ta||'', ds).length)) return 'stock';
    return 'ai';
  }
  function ai100(){ return st().cheDo === 'ai100'; }
  da.keHoach = function(){
    var s=st(), ds=cast(), kh=G.axn.doc(s.kichBan, ds, ai100() ? 14 : 34);   /* 100% AI: câu nói ≤ ~5 giây/cảnh */
    kh.canh.forEach(function(c,i){
      c.id = (i+1<10?'0':'')+(i+1);
      c.tuDong = ai100() ? 'ai' : tuDong(c, ds);
      c.khoa = c.id+'-'+bam(c.thoai||c.mo_ta||'');
      c.nhom = ai100() ? 'ai' : (s.nhom[c.khoa] || c.tuDong);
      c.khongRo = c.loai==='dien' && c.nhom!=='stock' && !G.axn.nguoiTrong(c.mo_ta||'', ds).length;
      if(c.nhom==='stock') c.nv = [];
      if(ai100() && c.loai==='dien' && !c.hanh_dong && !G.axn.nguoiTrong(c.mo_ta||'', ds).length){ c.nv = []; c.khongRo = false; }   /* cảnh không người (toàn cảnh…) */
    });
    return kh;
  };
  function tenNv(id){ return (cast().filter(function(n){ return n.id===id; })[0]||{}).ten || id; }
  function uocTinh(kh){
    var g={quay:0,stock:0,ai:0}; kh.canh.forEach(function(c){ g[c.nhom]+=c.giay; });
    /* T4 Kaggle: FastWan 3 bước ~4 phút/cảnh + khớp môi ~1,5 phút/cảnh nói + hậu kỳ ~1 phút (ước tính, chưa đo) */
    var gioGPU = kh.canh.filter(function(c){ return c.nhom==='ai'; }).reduce(function(t,c){ return t + 5 + (c.loai==='noi'?1.5:0); }, 0)/60;
    var phimThang = gioGPU>0 ? Math.floor(120/gioGPU) : 99;
    return { g:g, gioGPU:gioGPU, phimThang:Math.min(phimThang, 40) };
  }

  /* ── thao tác ── */
  da.dat = function(k,v){ st()[k]=v; luu(); ve(); };
  da.cheDo = function(v){ st().cheDo=v; luu(); ve(); };
  da.kichBan = function(v){ st().kichBan=v; luu(); var el=document.getElementById('da-bang'); if(el) el.innerHTML=veBang(da.keHoach()); };
  da.doiNhom = function(khoa, v){ st().nhom[khoa]=v; luu(); ve(); };
  da.mau = function(){ var s=st(); s.kichBan=MAU; s.nhom={}; luu(); ve(); };
  da.taoThuMuc = function(){
    var k=kd(), s=st(); if(!k) return U.toast('Chưa nối kho Drive — mở tab Kho phim.','err');
    k.goi('taoDuAn',{ten:s.ten}).then(function(d){ s.duAn=d.id; s.link=d.link; s.tep=null; luu(); ve(); U.toast('Đã tạo thư mục "'+d.ten+'" trên Drive','ok'); })
      .catch(function(e){ U.toast(e.message,'err'); });
  };
  da.kiemTep = function(){
    var k=kd(), s=st(); if(!k||!s.duAn) return;
    k.goi('dsDuAn',{duAn:s.duAn}).then(function(d){ s.tep=d.tep; luu(); ve(); }).catch(function(e){ U.toast(e.message,'err'); });
  };
  function goiKeHoach(kh, chiAI){
    var s=st(), dung={};
    /* mien_phi: động cơ chạy FastWan + MuseTalk trên Kaggle T4 */
    var canh = kh.canh.filter(function(c){ return !chiAI || c.nhom==='ai'; });
    canh.forEach(function(c){ c.nv.forEach(function(id){ dung[id]=1; }); });
    return { du_an:s.duAn, tieu_de:s.ten, khung:s.khung, ngon_ngu:(G.S.axN||{}).ngonNgu||'vi', chong_rung:!!s.chongRung, mien_phi:true,
      nhan_vat: cast().filter(function(n){ return dung[n.id]; }).map(function(n){
        return {id:n.id, ten:n.ten, vai:n.vai, gioi:n.gioi, tuoi:n.tuoi, giong_key:(n.gioi||'nam')+'-'+(n.tuoi||'lon'), anh:n.anhDrive||''}; }),
      canh: canh.map(function(c){ return {id:c.id, nhom:c.nhom, loai:c.loai, nv:c.nv, thoai:c.thoai||'', mo_ta:c.mo_ta||'',
        hanh_dong:c.hanh_dong||'', boi_canh_en:c.boi_canh_en, may:c.may, giay:c.giay}; }) };
  }
  da.dungAI = function(){
    var k=kd(), s=st(), kh=da.keHoach();
    if(!k||!s.duAn) return U.toast('Tạo thư mục dự án trên Drive trước.','err');
    var ai = kh.canh.filter(function(c){ return c.nhom==='ai'; });
    if(!ai.length) return U.toast('Không có cảnh AI nào.','err');
    var thieu = {}; ai.forEach(function(c){ c.nv.forEach(function(id){ var n=cast().filter(function(x){return x.id===id;})[0]; if(!n||!n.anhDrive) thieu[tenNv(id)]=1; }); });
    if(Object.keys(thieu).length) return U.toast('Cảnh AI cần ảnh mẫu của: '+Object.keys(thieu).join(', ')+' (gửi ở tab Làm phim nhanh).','err');
    k.goi('datAI',{ke_hoach:goiKeHoach(kh,true)}).then(function(d){ s.jobAI=d.jobid; s.ttAI={trangThai:'queued',buoc:'Đã gửi'}; luu(); ve(); da.theoDoi(); })
      .catch(function(e){ U.toast(e.message,'err'); });
  };
  /* 100% AI: một lần chạy Kaggle làm hết — ảnh → video → giọng → khớp môi → hậu kỳ → ráp → phim về Drive */
  da.lamAI100 = function(){
    var k=kd(), s=st(), kh=da.keHoach();
    if(!k||!s.duAn) return U.toast('Tạo thư mục dự án trên Drive trước.','err');
    if(!s.tep) return U.toast('Bấm "Kiểm tra tệp" để xưởng thấy ảnh anh/chị đã đưa vào.','err');
    var coAnh={}; s.tep.forEach(function(t){ if(t.nhom==='anh') coAnh[t.so]=1; });
    var thieu = kh.canh.filter(function(c){ return !coAnh[c.id] && !(c.nv[0] && (cast().filter(function(n){ return n.id===c.nv[0]; })[0]||{}).anhDrive); })
      .map(function(c){ return c.id; });
    if(thieu.length) return U.toast('Còn thiếu ảnh cho cảnh: '+thieu.join(', ')+' (đặt Anh/'+thieu[0]+'.jpg, hoặc gửi ảnh nhân vật ở tab Làm phim nhanh).','err');
    k.goi('datAI',{ke_hoach:goiKeHoach(kh,false), tron:true}).then(function(d){ s.jobAI=d.jobid; s.ttAI={trangThai:'queued',buoc:'Đã gửi việc'}; luu(); ve(); da.theoDoi(); })
      .catch(function(e){ U.toast(e.message,'err'); });
  };
  da.rap = function(){
    var k=kd(), s=st(), kh=da.keHoach();
    if(!k||!s.duAn) return U.toast('Tạo thư mục dự án trên Drive trước.','err');
    var co={}; (s.tep||[]).forEach(function(t){ co[t.so]=1; });
    var thieu = kh.canh.filter(function(c){ return !co[c.id]; }).map(function(c){ return c.id; });
    if(!s.tep) return U.toast('Bấm "Kiểm tra tệp" trước khi ráp.','err');
    if(thieu.length && !window.confirm('Còn thiếu tệp cảnh: '+thieu.join(', ')+'. Vẫn ráp (bỏ các cảnh thiếu)?')) return;
    k.goi('datRap',{ke_hoach:goiKeHoach(kh,false)}).then(function(d){ s.jobRap=d.jobid; s.ttRap={trangThai:'queued',buoc:'Đã gửi'}; luu(); ve(); da.theoDoi(); })
      .catch(function(e){ U.toast(e.message,'err'); });
  };
  da.theoDoi = function(){
    var k=kd(), s=st(); clearTimeout(da._t); if(!k) return;
    var viec=[['jobAI','ttAI'],['jobRap','ttRap']].filter(function(x){ return s[x[0]] && (!s[x[1]] || !/done|error/.test(s[x[1]].trangThai)); });
    if(!viec.length) return;
    Promise.all(viec.map(function(x){ return k.goi('trangThai',{jobid:s[x[0]]}).then(function(d){ s[x[1]]=d; }).catch(function(){}); }))
      .then(function(){ luu(); ve(); da._t=setTimeout(da.theoDoi, 30000); });
  };
  da.chepDS = function(){
    var t=(document.getElementById('da-ds-quay')||{}).innerText||'';
    if(navigator.clipboard) navigator.clipboard.writeText(t).then(function(){ U.toast('Đã chép danh sách quay.','ok'); });
  };

  /* ── giao diện ── */
  function chip(n){ return '<span class="bd-chip" style="border-color:'+NHOM[n][1]+';color:'+NHOM[n][1]+'">'+NHOM[n][0]+'</span>'; }
  function tenNoi(c){
    var b=(G.S.axBC||[]).filter(function(x){ return x.id===c.bc_id; })[0];
    return b ? b.ten : '';
  }
  function goiYAnh(c){
    if(!c.nv.length) return 'cảnh không người — '+(c.mo_ta||'toàn cảnh')+' (ảnh chụp hoặc ảnh tạo bằng Gemini)';
    var ai = c.nv.map(tenNv).join(' và '), noi = tenNoi(c);
    if(c.loai==='noi') return ai+(noi?' tại '+noi:'')+', '+((c.may&&c.may.co)==='can'?'cận mặt':'trung cảnh (ngang hông)')+', nhìn vào máy, miệng khép';
    return ai+(noi?' tại '+noi:'')+' — tư thế ĐẦU cảnh: '+(c.mo_ta||'');
  }
  function veBangAI(kh){
    var s=st(), u=uocTinh(kh), coAnh={}, coNv={};
    (s.tep||[]).forEach(function(t){ if(t.nhom==='anh') coAnh[t.so]=1; });
    cast().forEach(function(n){ if(n.anhDrive) coNv[n.id]=1; });
    var noi = kh.canh.filter(function(c){ return c.loai==='noi'; }).length;
    var o = '<div class="row" style="gap:8px;flex-wrap:wrap;align-items:center">'+
      '<span class="bd-chip">'+kh.canh.length+' cảnh · ~'+Math.round(kh.tongGiay/6)/10+' phút</span>'+
      '<span class="bd-chip">'+noi+' cảnh nói (khớp môi)</span><span class="bd-chip">'+(kh.canh.length-noi)+' cảnh diễn</span></div>'+
      '<p class="bd-tip" style="margin-top:6px">≈ '+(Math.round(u.gioGPU*10)/10)+' giờ GPU Kaggle cho phim này (ước tính, chưa đo thật) · Kaggle cho ~30 giờ/tuần → khoảng <b>'+u.phimThang+' phim/tháng</b>.</p>'+
      (kh.canhBao.length?'<p class="bd-tip" style="color:#B4720F">'+kh.canhBao.map(h).join('<br>')+'</p>':'');
    o += '<div class="gd-wrap" style="margin-top:8px"><table class="gd-tb"><thead><tr><th>#</th><th>Loại</th><th>Nội dung</th><th>Giây</th><th>Ảnh khung đầu (Anh/số.jpg)</th></tr></thead><tbody>'+
      kh.canh.map(function(c){
        var nd = (c.nv.length?h(c.nv.map(tenNv).join(' + '))+' · ':'')+(c.thoai?'“'+h(c.thoai)+'”':h(c.mo_ta||''))+
          '<br><span class="tiny muted">Ảnh nên có: '+h(goiYAnh(c))+'</span>'+
          (c.khongRo?'<br><span class="tiny" style="color:#B4720F">⚠ Mô tả không nhắc ai trong dàn nhân vật — đang dùng '+h(tenNv(c.nv[0]))+'. Ảnh Anh/'+c.id+'.jpg của anh/chị sẽ quyết định ai xuất hiện.</span>':'');
        var anh = coAnh[c.id] ? '<span style="color:#0B7350">✓ Anh/'+c.id+'.jpg</span>'
          : (c.nv[0] && coNv[c.nv[0]] ? '<span style="color:#B4720F">dùng ảnh nhân vật</span><br><span class="tiny muted">nên thêm Anh/'+c.id+'.jpg</span>'
          : '<span style="color:#B42318">thiếu Anh/'+c.id+'.jpg</span>');
        return '<tr><td>'+c.id+'</td><td>'+(c.loai==='noi'?'🗣 Nói':'🎬 Diễn')+'</td><td style="min-width:240px">'+nd+'</td><td>'+c.giay+'</td><td>'+(s.tep?anh:'<span class="tiny muted">Anh/'+c.id+'.jpg</span>')+'</td></tr>'; }).join('')+
      '</tbody></table></div>';
    return o;
  }
  function veBang(kh){
    if(ai100()) return veBangAI(kh);
    var s=st(), co={}, u=uocTinh(kh);
    (s.tep||[]).forEach(function(t){ co[t.so]=t.nhom; });
    var o = '<div class="row" style="gap:8px;flex-wrap:wrap;align-items:center">'+
      '<span class="bd-chip">'+kh.canh.length+' cảnh · ~'+Math.round(kh.tongGiay/6)/10+' phút</span>'+
      Object.keys(NHOM).map(function(n){ return chip(n).replace('</span>',' · '+Math.round(u.g[n])+'s</span>'); }).join('')+'</div>'+
      '<p class="bd-tip" style="margin-top:6px">AI chỉ chiếm '+(kh.tongGiay?Math.round(u.g.ai/kh.tongGiay*100):0)+'% thời lượng → ≈ '+(Math.round(u.gioGPU*10)/10)+' giờ GPU Kaggle mỗi phim. '+
        'Kaggle cho ~30 giờ/tuần → làm được khoảng <b>'+u.phimThang+' phim/tháng</b> (phần quay thật và ráp không tốn giờ GPU).</p>'+
      (kh.canhBao.length?'<p class="bd-tip" style="color:#B4720F">'+kh.canhBao.map(h).join('<br>')+'</p>':'');
    o += '<div class="gd-wrap" style="margin-top:8px"><table class="gd-tb"><thead><tr><th>#</th><th>Làm bằng</th><th>Nội dung</th><th>Giây</th><th>Tệp trên Drive</th></tr></thead><tbody>'+
      kh.canh.map(function(c){
        var noi = (c.nv.length?h(c.nv.map(tenNv).join(' + '))+' · ':'')+(c.thoai?'“'+h(c.thoai.slice(0,80))+(c.thoai.length>80?'…':'')+'”':h((c.mo_ta||'').slice(0,80)))+
          (c.khongRo?'<br><span class="tiny" style="color:#B4720F">⚠ Mô tả không nhắc ai trong dàn nhân vật — đang tạm dùng '+h(tenNv(c.nv[0]))+'. Thêm nhân vật ở tab Làm phim nhanh nếu cần.</span>':'');
        var tep = s.tep ? (co[c.id] ? (co[c.id]===c.nhom?'<span style="color:#0B7350">✓ '+c.id+'</span>':'<span style="color:#B4720F">✓ '+c.id+' (ở thư mục '+h(THU_MUC[co[c.id]]||co[c.id])+')</span>') : '<span style="color:#B42318">thiếu '+c.id+'.mp4</span>') : '<span class="tiny muted">'+c.id+'.mp4 → '+THU_MUC[c.nhom]+'</span>';
        return '<tr><td>'+c.id+'</td><td><select onchange="G.axda.doiNhom(\''+c.khoa+'\',this.value)" style="padding:4px;border:1px solid var(--line);border-radius:8px">'+
          Object.keys(NHOM).map(function(n){ return '<option value="'+n+'"'+(c.nhom===n?' selected':'')+'>'+NHOM[n][0]+(c.tuDong===n?' (gợi ý)':'')+'</option>'; }).join('')+'</select></td>'+
          '<td style="min-width:220px">'+noi+'</td><td>'+c.giay+'</td><td>'+tep+'</td></tr>'; }).join('')+'</tbody></table></div>';
    return o;
  }
  function veTT(tt, ten){
    if(!tt) return '';
    var pt = tt.trangThai==='done'?100:Math.max(2,+tt.phanTram||0), mau = tt.trangThai==='error'?'#B42318':(tt.trangThai==='done'?'#0B7350':'var(--gita)');
    return '<div style="margin-top:8px"><div class="tiny"><b>'+ten+':</b> '+h(tt.buoc||tt.loi||'')+'</div>'+
      '<div style="height:8px;border-radius:5px;background:var(--line);overflow:hidden;margin-top:4px"><div style="height:100%;width:'+pt+'%;background:'+mau+'"></div></div></div>';
  }
  da.ve = function(){
    var s=st(), kh=da.keHoach(), k=kd(), doc=s.khung!=='ngang';
    if((s.jobAI && s.ttAI && !/done|error/.test(s.ttAI.trangThai)) || (s.jobRap && s.ttRap && !/done|error/.test(s.ttRap.trangThai))) setTimeout(da.theoDoi, 0);
    var A = ai100();
    var o = U.sec('Dự án phim', A ? 'Video 4–8 phút 100% AI từ ảnh anh/chị cung cấp · miễn phí (Kaggle) · khớp môi tiếng Việt · tự ráp, lưu Google Drive'
                                  : 'Video 4–8 phút cao cấp, miễn phí: quay thật phần chính · video nền miễn phí · AI cho phần không quay được → ráp tự động, lưu Google Drive');
    o += '<div class="row mb" style="gap:8px;flex-wrap:wrap">'+
      '<button class="btn sm '+(A?'':'ghost')+'" onclick="G.axda.cheDo(\'ai100\')">✨ 100% AI từ ảnh</button>'+
      '<button class="btn sm '+(A?'ghost':'')+'" onclick="G.axda.cheDo(\'lai\')">🎥 Quay thật + AI</button></div>';
    if(!k) o += '<div class="card pad-sm mb"><p class="tiny" style="color:#B4720F">Cần nối kho Google Drive trước (tab 🗄 Kho phim → Cài đặt kho Drive).</p></div>';
    /* 1 · kịch bản */
    o += '<div class="card pad-sm mb"><b class="sm">① Kịch bản</b>'+
      '<div class="row mt" style="gap:8px;flex-wrap:wrap"><input type="text" value="'+h(s.ten)+'" onchange="G.axda.dat(\'ten\',this.value)" placeholder="Tên dự án" style="flex:1;min-width:200px;padding:8px;border:1px solid var(--line);border-radius:8px">'+
      '<select onchange="G.axda.dat(\'khung\',this.value)" style="padding:6px;border:1px solid var(--line);border-radius:8px"><option value="doc"'+(doc?' selected':'')+'>Dọc 9:16</option><option value="ngang"'+(doc?'':' selected')+'>Ngang 16:9</option></select>'+
      '<button class="btn ghost sm" onclick="G.axda.mau()">Kịch bản mẫu</button></div>'+
      '<p class="tiny muted" style="margin:6px 0">Viết như tab Làm phim nhanh: <b>[Nơi quay]</b> · <b>Tên: lời thoại</b> · câu hành động. Đoạn chỉ có <b>[cảnh]</b> không người → '+(A?'cảnh toàn cảnh (cần ảnh riêng)':'video nền')+'.</p>'+
      '<textarea rows="9" oninput="G.axda.kichBan(this.value)" style="width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--line);border-radius:10px;font-size:14px;line-height:1.5">'+h(s.kichBan)+'</textarea></div>';
    /* 2 · phân loại */
    o += '<div class="card pad-sm mb"><b class="sm">② '+(A?'Phân cảnh & ảnh cần có':'Xưởng chia việc từng cảnh')+'</b> <span class="tiny muted">'+(A?'(câu nói dài được tách cảnh ≤ ~5 giây)':'(đổi được ở cột "Làm bằng")')+'</span><div id="da-bang" style="margin-top:8px">'+veBang(kh)+'</div></div>';
    /* 3 · thư mục Drive */
    o += '<div class="card pad-sm mb"><b class="sm">③ Thư mục dự án trên Google Drive</b><div class="row mt" style="gap:8px;flex-wrap:wrap">'+
      (s.duAn ? '<a class="btn sm" target="_blank" rel="noopener" href="'+h(s.link)+'">📁 Mở thư mục dự án</a><button class="btn ghost sm" onclick="G.axda.kiemTep()">↻ Kiểm tra tệp</button>'
              : '<button class="btn sm" onclick="G.axda.taoThuMuc()">📁 Tạo thư mục dự án</button>')+'</div>'+
      (A ? '<p class="bd-tip" style="margin-top:6px"><b>Anh/</b>: ảnh khung đầu từng cảnh, đặt tên đúng số cảnh <b>01.jpg, 02.jpg…</b> — đúng người, đúng nơi, đúng tư thế lúc bắt đầu cảnh (ảnh chụp, hoặc ảnh tạo bằng ứng dụng Gemini rồi tải về). '+
             '<b>Giong/</b> (tuỳ chọn): mỗi nhân vật 1 tệp đọc rõ 10–20 giây, đặt tên theo nhân vật, vd <b>'+h(((cast()[0]||{}).ten)||'Trainer')+'.wav</b> — thiếu thì dùng giọng có sẵn theo giới tính. <b>Nhac/</b>: 1 tệp nhạc nền mp3.</p></div>'
         : '<p class="bd-tip" style="margin-top:6px">Trong thư mục có <b>Quay-that · Stock · AI · Nhac</b>. Đặt tên tệp đúng số cảnh: <b>01.mp4, 02.mov…</b> (điện thoại quay xong đổi tên rồi kéo vào). Thư mục Nhac: thả 1 tệp nhạc nền mp3.</p></div>');
    if(A){
      var xongA = s.ttAI && s.ttAI.trangThai==='done' && s.ttAI.phimId;
      o += '<div class="card pad-sm mb"><b class="sm">④ Làm phim 100% AI</b> <span class="tiny muted">· Kaggle GPU miễn phí · FastWan 2.2 + khớp môi MuseTalk · 1080p · thường vài giờ</span>'+
        '<div class="row mt"><button class="btn" onclick="G.axda.lamAI100()">🎬 Làm phim</button></div>'+veTT(s.ttAI,'Tiến độ')+
        (xongA && G.khoDrive ? '<div style="position:relative;width:100%;max-width:'+(doc?'420px':'720px')+';aspect-ratio:'+(doc?'9/16':'16/9')+';margin:10px auto 0;max-height:75vh">'+
          '<iframe src="'+h(G.khoDrive.xem(s.ttAI.phimId))+'" allow="autoplay; fullscreen" allowfullscreen style="position:absolute;inset:0;width:100%;height:100%;border:0;border-radius:12px;background:#000"></iframe></div>'+
          '<div class="row mt" style="gap:8px;flex-wrap:wrap"><a class="btn" target="_blank" rel="noopener" href="'+h(G.khoDrive.link(s.ttAI.phimId))+'">⬇ Mở / tải trên Drive</a>'+
          (s.ttAI.phimPhuDeId?'<a class="btn ghost" target="_blank" rel="noopener" href="'+h(G.khoDrive.link(s.ttAI.phimPhuDeId))+'">Bản có phụ đề</a>':'')+'</div>' : '')+
        '<p class="bd-tip" style="margin-top:6px">Xưởng tự: giọng nói từng câu → video từ ảnh của anh/chị → khớp môi tiếng Việt → giữ mặt, làm nét → phụ đề, thẻ tên, nhạc → phim 1080p vào Drive/Phim. '+
          'Cảnh nào không khớp môi được sẽ để mặt tự nhiên + lồng tiếng, không giả khẩu hình.</p></div>';
      return o;
    }
    /* 4 · danh sách quay */
    var quay = kh.canh.filter(function(c){ return c.nhom==='quay'; });
    o += '<details class="card pad-sm mb"'+(quay.length?' open':'')+'><summary class="sm" style="cursor:pointer"><b>④ Danh sách quay điện thoại</b> <span class="tiny muted">· '+quay.length+' cảnh · một buổi quay</span></summary>'+
      '<div id="da-ds-quay" class="tiny" style="line-height:1.7;margin-top:8px;color:var(--ink-2)">'+
      '<p><b>Chuẩn bị:</b> điện thoại '+(doc?'quay DỌC':'quay NGANG')+' 1080p 30fps · đặt chân máy ngang tầm mắt · mic cài áo · đứng gần cửa sổ hoặc đèn, không ngược sáng · cách máy 1,5–2m · im lặng 1 giây trước và sau mỗi câu · mỗi cảnh quay 2 lần, giữ bản tốt.</p>'+
      quay.map(function(c){ return '<p><b>Cảnh '+c.id+'</b> · '+h(c.nv.map(tenNv).join(' + ')||'—')+' · khung '+(CO[c.may&&c.may.co]||'trung')+' · nơi quay: '+h((c.bc_id||'').replace('bc-',''))+'<br>'+
        (c.thoai?'Nói: “'+h(c.thoai)+'”':'Diễn: '+h(c.mo_ta||''))+'<br><i>Lưu tên '+c.id+'.mp4 → thư mục Quay-that</i></p>'; }).join('')+'</div>'+
      '<button class="btn ghost sm" onclick="G.axda.chepDS()">Chép danh sách</button></details>';
    /* 5 · video nền */
    var stock = kh.canh.filter(function(c){ return c.nhom==='stock'; });
    if(stock.length) o += '<div class="card pad-sm mb"><b class="sm">⑤ Video nền miễn phí</b> <span class="tiny muted">(Pexels/Pixabay: dùng thương mại được, không cần ghi nguồn)</span>'+
      stock.map(function(c){ var kw = tuKhoa(c), q = encodeURIComponent(kw);
        return '<div class="row" style="gap:8px;flex-wrap:wrap;align-items:center;margin-top:6px"><span class="tiny"><b>Cảnh '+c.id+'</b> · '+h((c.mo_ta||'').slice(0,60))+' · ~'+c.giay+'s</span>'+
          '<a class="btn ghost sm" target="_blank" rel="noopener" href="https://www.pexels.com/search/videos/'+q+'/?orientation='+(doc?'portrait':'landscape')+'">Pexels: '+h(kw)+'</a>'+
          '<a class="btn ghost sm" target="_blank" rel="noopener" href="https://pixabay.com/videos/search/'+q+'/">Pixabay</a></div>'; }).join('')+
      '<p class="bd-tip" style="margin-top:6px">Tải bản 1080p, đổi tên đúng số cảnh rồi kéo vào thư mục Stock. Tránh đoạn có logo thương hiệu hay người nổi tiếng.</p></div>';
    /* 6 · AI */
    var ai = kh.canh.filter(function(c){ return c.nhom==='ai'; });
    if(ai.length) o += '<div class="card pad-sm mb"><b class="sm">⑥ Cảnh AI</b> <span class="tiny muted">· '+ai.length+' cảnh · Kaggle GPU miễn phí, thường vài giờ</span>'+
      '<div class="row mt"><button class="btn sm" onclick="G.axda.dungAI()">✨ Dựng cảnh AI</button></div>'+veTT(s.ttAI,'Cảnh AI')+
      '<p class="bd-tip" style="margin-top:6px">Dùng ảnh mẫu đã gửi ở tab Làm phim nhanh. Xong, cảnh tự vào thư mục AI của dự án.</p></div>';
    /* 7 · ráp */
    var xong = s.ttRap && s.ttRap.trangThai==='done' && s.ttRap.phimId;
    o += '<div class="card pad-sm mb"><b class="sm">⑦ Ráp phim</b> <span class="tiny muted">· máy GitHub miễn phí · 1080p · giọng chuẩn phát sóng · màu · phụ đề · thẻ tên · nhạc</span>'+
      '<div class="row mt" style="gap:8px;flex-wrap:wrap;align-items:center"><button class="btn" onclick="G.axda.rap()">🎬 Ráp phim</button>'+
      '<label class="tiny" style="display:flex;gap:6px;align-items:center"><input type="checkbox"'+(s.chongRung?' checked':'')+' onchange="G.axda.dat(\'chongRung\',this.checked)"> Chống rung (quay cầm tay)</label></div>'+
      veTT(s.ttRap,'Ráp')+
      (xong && G.khoDrive ? '<div style="position:relative;width:100%;max-width:'+(doc?'420px':'720px')+';aspect-ratio:'+(doc?'9/16':'16/9')+';margin:10px auto 0;max-height:75vh">'+
        '<iframe src="'+h(G.khoDrive.xem(s.ttRap.phimId))+'" allow="autoplay; fullscreen" allowfullscreen style="position:absolute;inset:0;width:100%;height:100%;border:0;border-radius:12px;background:#000"></iframe></div>'+
        '<div class="row mt" style="gap:8px;flex-wrap:wrap"><a class="btn" target="_blank" rel="noopener" href="'+h(G.khoDrive.link(s.ttRap.phimId))+'">⬇ Mở / tải trên Drive</a>'+
        (s.ttRap.phimPhuDeId?'<a class="btn ghost" target="_blank" rel="noopener" href="'+h(G.khoDrive.link(s.ttRap.phimPhuDeId))+'">Bản có phụ đề</a>':'')+'</div>' : '')+'</div>';
    return o;
  };
})();

})();

